# Central exception handling for async tasks
class AsyncTaskManager:
    """
    Central exception handling mechanism for asyncio tasks.
    Provides reliable exception handling and task tracking.
    """
    
    def __init__(self):
        self.background_tasks = set()
        self._lock = asyncio.Lock()
    
    def create_task_sync(self, coro, task_name="unnamed", callback=None):
        """
        Create a background task with proper exception handling (synchronous wrapper).
        This can be called from both sync and async contexts.
        
        Args:
            coro: The coroutine to execute
            task_name: Descriptive name for the task (for logging)
            callback: Optional callback function(task) to call on completion
        
        Returns:
            The created task object
        """
        async def wrapped_coro():
            try:
                return await coro
            except Exception as e:
                logging.error(f"Task '{task_name}' failed: {e}", exc_info=True)
                raise  # Re-raise to ensure proper exception propagation
        
        task = asyncio.create_task(wrapped_coro())
        
        # Add proper exception handling callback
        def handle_completion(t):
            try:
                if t.exception():
                    logging.error(f"Task '{task_name}' exception: {t.exception()}", exc_info=True)
                if callback:
                    callback(t)
            except Exception as e:
                logging.error(f"Error in task completion callback for '{task_name}': {e}", exc_info=True)
            finally:
                # Clean up task from tracking set synchronously to avoid race condition
                if task in self.background_tasks:
                    self.background_tasks.discard(task)
        
        task.add_done_callback(handle_completion)
        
        # Track the task synchronously but ensure thread safety
        # Use a simple add since the callback handles removal with proper checking
        self.background_tasks.add(task)
        
        return task
    
    async def create_task(self, coro, task_name="unnamed", callback=None):
        """
        Create a background task with proper exception handling (async version).
        
        Args:
            coro: The coroutine to execute
            task_name: Descriptive name for the task (for logging)
            callback: Optional callback function(task) to call on completion
        
        Returns:
            The created task object
        """
        async def wrapped_coro():
            try:
                return await coro
            except Exception as e:
                logging.error(f"Task '{task_name}' failed: {e}", exc_info=True)
                raise  # Re-raise to ensure proper exception propagation
        
        task = asyncio.create_task(wrapped_coro())
        
        # Add proper exception handling callback
        def handle_completion(t):
            try:
                if t.exception():
                    logging.error(f"Task '{task_name}' exception: {t.exception()}", exc_info=True)
                if callback:
                    callback(t)
            except Exception as e:
                logging.error(f"Error in task completion callback for '{task_name}': {e}", exc_info=True)
            finally:
                # Clean up task from tracking set synchronously to avoid race condition
                if task in self.background_tasks:
                    self.background_tasks.discard(task)
        
        task.add_done_callback(handle_completion)
        
        # Track the task
        async with self._lock:
            self.background_tasks.add(task)
        
        return task
    
    async def _remove_task(self, task):
        """Remove a completed task from tracking set"""
        async with self._lock:
            self.background_tasks.discard(task)
    
    async def wait_all(self, timeout=None):
        """
        Wait for all tracked background tasks to complete.
        
        Args:
            timeout: Optional timeout in seconds
        """
        if not self.background_tasks:
            return
        
        try:
            await asyncio.wait_for(
                asyncio.gather(*self.background_tasks, return_exceptions=True),
                timeout=timeout
            )
        except asyncio.TimeoutError:
            logging.warning(f"Timeout waiting for {len(self.background_tasks)} background tasks")
        except Exception as e:
            logging.error(f"Error waiting for background tasks: {e}", exc_info=True)
    
    async def cancel_all(self):
        """
        Cancel all tracked background tasks.
        Ensures proper cleanup and prevents orphaned tasks.
        """
        if not self.background_tasks:
            return
        
        logging.info(f"Cancelling {len(self.background_tasks)} background tasks")
        
        cancellation_failures = 0
        async with self._lock:
            for task in self.background_tasks:
                if not task.done():
                    task.cancel()
                    try:
                        await task
                    except asyncio.CancelledError:
                        pass
                    except Exception as e:
                        logging.warning(f"Error during task cancellation: {e}")
                        cancellation_failures += 1
            
            self.background_tasks.clear()
        
        if cancellation_failures > 0:
            logging.warning(f"Task cancellation completed with {cancellation_failures} failures")

class BackgroundTaskManager:
    """
    Manager for background async tasks with proper lifecycle management.
    Provides add_task and cancel_all methods for managing background tasks.
    """
    
    def __init__(self):
        self.background_tasks = set()
        self._lock = asyncio.Lock()
    
    def add_task(self, coro, task_name="unnamed"):
        """
        Add a background task with proper exception handling.
        
        Args:
            coro: The coroutine to execute
            task_name: Descriptive name for the task (for logging)
        
        Returns:
            The created task object
        """
        async def wrapped_coro():
            try:
                return await coro
            except Exception as e:
                logging.error(f"Background task '{task_name}' failed: {e}", exc_info=True)
                raise
        
        task = asyncio.create_task(wrapped_coro())
        
        # Add proper exception handling callback
        def handle_completion(t):
            try:
                if t.exception():
                    logging.error(f"Background task '{task_name}' exception: {t.exception()}", exc_info=True)
            except Exception as e:
                logging.error(f"Error in background task completion callback for '{task_name}': {e}", exc_info=True)
            finally:
                # Clean up task from tracking set synchronously to avoid race condition
                if task in self.background_tasks:
                    self.background_tasks.discard(task)
        
        task.add_done_callback(handle_completion)
        
        # Track the task synchronously but ensure thread safety
        # Use a simple add since the callback handles removal with proper checking
        self.background_tasks.add(task)
        
        return task
    
    async def cancel_all(self):
        """Cancel all tracked background tasks."""
        if not self.background_tasks:
            return
        
        logging.info(f"Cancelling {len(self.background_tasks)} background tasks")
        
        cancellation_failures = 0
        try:
            # Cancel all tasks
            for task in self.background_tasks:
                if not task.done():
                    task.cancel()
            
            # Wait for tasks to be cancelled (with timeout)
            if self.background_tasks:
                await asyncio.wait(self.background_tasks, timeout=5.0, return_when=asyncio.ALL_COMPLETED)
            
            self.background_tasks.clear()
            logging.info("All background tasks cancelled successfully")
        except asyncio.TimeoutError:
            logging.warning(f"Timeout waiting for {len(self.background_tasks)} background tasks to cancel")
            self.background_tasks.clear()
        except Exception as e:
            logging.error(f"Error cancelling background tasks: {e}", exc_info=True)
            cancellation_failures += 1
            self.background_tasks.clear()
        
        if cancellation_failures > 0:
            logging.warning(f"Task cancellation completed with {cancellation_failures} failures")

# Global async task manager instance
ASYNC_TASK_MANAGER = AsyncTaskManager()

# Security utility functions
def validate_checkpoint_filename(filename):
    """
    Validate checkpoint filename to prevent path traversal attacks.
    
    Args:
        filename: The filename to validate
        
    Returns:
        bool: True if filename is safe, False otherwise
    """
    import re
    import os
    
    # Check for null bytes
    if '\x00' in filename:
        return False
    
    # Extract just the filename (no path components)
    safe_filename = os.path.basename(filename)
    
    # Ensure basename didn't change (no path traversal)
    if safe_filename != filename:
        return False
    
    # Allow only checkpoint_<timestamp>.json pattern
    # timestamp should be digits only
    pattern = r'^checkpoint_\d+\.json$'
    if not re.match(pattern, safe_filename):
        return False
    
    # Ensure no path traversal characters (double-check)
    if '..' in safe_filename or '/' in safe_filename or '\\' in safe_filename:
        return False
    
    # Check for absolute path attempts
    if os.path.isabs(filename):
        return False
    
    # Validate character set (only alphanumeric, underscore, and dot)
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.')
    if not all(c in allowed_chars for c in safe_filename):
        return False
    
    return True

