def create_ssl_context(verify=True):
    context = ssl.create_default_context()
    if not verify:
        if DISABLE_SSL_VERIFICATION:
            warnings.warn(
                "SSL/TLS verification is DISABLED. This makes connections vulnerable to MITM attacks. "
                "Only use for authorized testing in isolated environments.",
                SecurityWarning
            )
            context.check_hostname = False
            context.verify_mode = ssl.CERT_NONE
        else:
            logging.warning("SSL verification requested to be disabled but not allowed. Using secure defaults.")
    return context

class SecurityWarning(Warning):
    """Custom warning for security-related issues during scanning."""
    def __init__(self, message, severity="medium", cwe=None):
        Warning.__init__(self, message)
        self.message = message
        self.severity = severity
        self.cwe = cwe
    
    def __str__(self):
        severity_str = f"[{self.severity.upper()}] " if self.severity else ""
        cwe_str = f" (CWE: {self.cwe})" if self.cwe else ""
        return f"{severity_str}Security Warning: {self.message}{cwe_str}"

