    @staticmethod
    def cors_misconfig(url: str, session: Any, selenium_available: bool = False) -> Optional[Dict[str, Any]]:
        """
        Enhanced CORS Misconfiguration Detection with Origin reflection testing.
        
        Many CORS misconfigurations are per-endpoint and require Origin reflection.
        This implementation:
        1. Sends Origin header with GET request to actual resource (not just OPTIONS)
        2. Checks Vary: Origin header for proper CORS implementation
        3. Verifies if reflected ACAO matches exact sent origin (not just wildcard)
        4. Tests for null origin misconfiguration (common in enterprise environments)
        """
        test_origin = "https://evil.com"
        
        try:
            # Test 1: GET request with Origin header (main resource access)
            headers = {"Origin": test_origin}
            resp = session.get(url, headers=headers, timeout=DEFAULT_HEALTH_CHECK_TIMEOUT)
            acao = resp.headers.get("Access-Control-Allow-Origin", "")
            vary_header = resp.headers.get("Vary", "")
            
            # Check for wildcard misconfiguration
            if acao == '*':
                confidence = calculate_evidence_based_confidence(
                    evidence_strength='high',
                    baseline_excluded=True,
                    multiple_confirmations=False,
                    specificity='high',
                    false_positive_resistance='medium'
                )
                return {
                    "type":"CORS Misconfiguration",
                    "url":url,
                    "evidence":f"ACAO: {acao} (wildcard)",
                    "severity":"Medium",
                    "confidence":confidence
                }
            
            # Check for exact origin reflection (potential misconfiguration)
            if acao == test_origin:
                # Check if Vary: Origin is present (proper implementation)
                if "origin" not in vary_header.lower():
                    # Missing Vary: Origin header - potential misconfiguration
                    confidence = calculate_evidence_based_confidence(
                        evidence_strength='high',
                        baseline_excluded=True,
                        multiple_confirmations=True,
                        specificity='high',
                        false_positive_resistance='high'
                    )
                    return {
                        "type":"CORS Misconfiguration",
                        "url":url,
                        "evidence":f"ACAO reflects exact origin without Vary: Origin (ACAO: {acao})",
                        "severity":"Medium",
                        "confidence":confidence
                    }
                else:
                    # Origin reflection with Vary: Origin - might be intentional
                    # Check for credentials
                    acac = resp.headers.get("Access-Control-Allow-Credentials", "")
                    if acac == "true":
                        # Origin reflection + credentials = potential misconfiguration
                        confidence = calculate_evidence_based_confidence(
                            evidence_strength='high',
                            baseline_excluded=True,
                            multiple_confirmations=True,
                            specificity='high',
                            false_positive_resistance='high'
                        )
                        return {
                            "type":"CORS Credentialed Misconfiguration",
                            "url":url,
                            "evidence":f"ACAO: {acao}, ACAC: {acac}, Vary: {vary_header}",
                            "severity":"High",
                            "confidence":confidence
                        }
            
            # Test 2: Null origin test (common enterprise misconfiguration)
            try:
                null_headers = {"Origin": "null"}
                null_resp = session.get(url, headers=null_headers, timeout=DEFAULT_HEALTH_CHECK_TIMEOUT)
                null_acao = null_resp.headers.get("Access-Control-Allow-Origin", "")
                
                if null_acao == "null":
                    confidence = calculate_evidence_based_confidence(
                        evidence_strength='high',
                        baseline_excluded=True,
                        multiple_confirmations=False,
                        specificity='high',
                        false_positive_resistance='medium'
                    )
                    return {
                        "type":"CORS Misconfiguration",
                        "url":url,
                        "evidence":f"ACAO: null (null origin reflection)",
                        "severity":"Medium",
                        "confidence":confidence
                    }
            except Exception as e:
                logging.debug(f"Null origin test error: {e}")
            
            # Test 2: OPTIONS preflight request (additional verification)
            try:
                options_headers = {
                    "Origin": test_origin,
                    "Access-Control-Request-Method": "GET",
                    "Access-Control-Request-Headers": "Authorization, Content-Type"
                }
                options_resp = session.options(url, headers=options_headers, timeout=DEFAULT_HEALTH_CHECK_TIMEOUT)
                acao_options = options_resp.headers.get("Access-Control-Allow-Origin", "")
                acac_options = options_resp.headers.get("Access-Control-Allow-Credentials", "")
                
                # Check for credentialed misconfiguration in preflight
                if acao_options == test_origin and acac_options == "true":
                    confidence = calculate_evidence_based_confidence(
                        evidence_strength='high',
                        baseline_excluded=True,
                        multiple_confirmations=True,
                        specificity='high',
                        false_positive_resistance='high'
                    )
                    return {
                        "type":"CORS Credentialed Misconfiguration",
                        "url":url,
                        "evidence":f"Preflight ACAO: {acao_options}, ACAC: {acac_options}",
                        "severity":"High",
                        "confidence":confidence
                    }
            except Exception as e:
                logging.warning(f"CORS preflight test error: {e}")
            
        except Exception as e:
            logging.warning(f"CORS check error: {e}")
        
        return None
    @staticmethod
    
    def jwt_test(token: str, public_key: Optional[str] = None) -> List[Dict[str, Any]]:
        if not JWT_AVAILABLE:
            logging.warning("JWT testing skipped - pyjwt library not available")
            return []
        vulns = []
        try:
            decoded = pyjwt.decode(token, options={"verify_signature": False})
            if decoded:
                header = pyjwt.get_unverified_header(token)
                if header.get('alg') != 'none':
                    try:
                        pyjwt.encode(decoded, key='', algorithm='none')
                        confidence = calculate_evidence_based_confidence(
                            evidence_strength='critical',
                            baseline_excluded=True,
                            multiple_confirmations=True,
                            specificity='high',
                            false_positive_resistance='high'
                        )
                        vulns.append({"type":"JWT None Algorithm","confidence":confidence,"evidence":"Token accepted with alg=none"})
                    except Exception as e:
                        logging.debug(f"JWT none algorithm test failed: {e}")
                if 'kid' in header:
                    kid_payloads = [
                        "../../../../dev/null",
                        "http://attacker.com/key.pem",
                        "../../../../etc/passwd",
                        "..\\..\\..\\..\\windows\\win.ini",
                        "http://evil.com/key.pem",
                        "file:///etc/passwd",
                        "path/to/key",
                        "null",
                        ""
                    ]
                    for kid_payload in kid_payloads:
                        try:
                            test_header = header.copy()
                            test_header['kid'] = kid_payload
                            test_token = pyjwt.encode(decoded, key='', algorithm='HS256', headers=test_header)
                            confidence = calculate_evidence_based_confidence(
                                evidence_strength='high',
                                baseline_excluded=True,
                                multiple_confirmations=False,
                                specificity='high',
                                false_positive_resistance='medium'
                            )
                            vulns.append({"type":"JWT kid Injection","confidence":confidence,"evidence":f"kid accepts path traversal: {kid_payload}"})
                            break
                        except Exception as e:
                            logging.debug(f"JWT kid injection test failed: {e}")
                jku_payloads = [
                    "http://localhost:8080/.well-known/jwks.json",
                    "http://127.0.0.1:8080/jwks.json",
                    "http://169.254.169.254/jwks.json",
                    "http://attacker.com/jwks.json",
                    "http://evil.com/malicious_jwks.json",
                    "file:///etc/passwd",
                    "https://internal.company.local/jwks.json",
                    "http://metadata.google.internal/jwks.json",
                ]
                for jku_payload in jku_payloads:
                    try:
                        test_header = header.copy()
                        test_header['jku'] = jku_payload
                        test_token = pyjwt.encode(decoded, key='', algorithm='HS256', headers=test_header)
                        confidence = calculate_evidence_based_confidence(
                            evidence_strength='high',
                            baseline_excluded=True,
                            multiple_confirmations=False,
                            specificity='high',
                            false_positive_resistance='medium'
                        )
                        vulns.append({"type":"JWT jku Injection","confidence":confidence,"evidence":f"jku accepts arbitrary URL: {jku_payload}"})
                        break
                    except Exception as e:
                        logging.debug(f"JWT jku injection test failed: {e}")
        except Exception as e:
            logging.warning(f"JWT decode error: {e}")
        weak_secrets = ['secret','key','password','123456']
        for sec in weak_secrets:
            try:
                pyjwt.decode(token, sec, algorithms=['HS256'])
                confidence = calculate_evidence_based_confidence(
                    evidence_strength='high',
                    baseline_excluded=True,
                    multiple_confirmations=False,
                    specificity='high',
                    false_positive_resistance='high'
                )
                vulns.append({"type":"JWT Weak Secret","confidence":confidence,"evidence":f"HMAC secret: {sec}"})
                break
            except Exception as e:
                logging.debug(f"JWT weak secret test failed for {sec}: {e}")
        if public_key:
            try:
                payload = pyjwt.decode(token, public_key, algorithms=['RS256'])
                forged = pyjwt.encode(payload, public_key, algorithm='HS256')
                if forged != token:
                    confidence = calculate_evidence_based_confidence(
                        evidence_strength='high',
                        baseline_excluded=True,
                        multiple_confirmations=True,
                        specificity='high',
                        false_positive_resistance='high'
                    )
                    vulns.append({"type":"JWT Algorithm Confusion","confidence":confidence,"evidence":"RS256 to HS256 possible"})
            except Exception as e:
                logging.debug(f"JWT algorithm confusion test failed: {e}")
        return vulns
