class DiskBasedURLStorage:
    """
    Disk-based URL storage with pagination for large-scale scanning.
    Replaces in-memory sets/lists with SQLite database for scalability.
    """
    
    def __init__(self, db_path='url_storage.db'):
        self.db_path = db_path
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.lock = threading.Lock()
        self._init_tables()
        
    def _init_tables(self):
        """Initialize database tables for URL storage"""
        with self.lock:
            self.conn.execute('''CREATE TABLE IF NOT EXISTS visited_urls
                             (url TEXT PRIMARY KEY, timestamp TEXT, depth INTEGER)''')
            self.conn.execute('''CREATE TABLE IF NOT EXISTS crawled_pages
                             (id INTEGER PRIMARY KEY AUTOINCREMENT, url TEXT, 
                              content_hash TEXT, html_path TEXT, timestamp TEXT, 
                              depth INTEGER, status_code INTEGER)''')
            self.conn.execute('''CREATE TABLE IF NOT EXISTS parameters
                             (id INTEGER PRIMARY KEY AUTOINCREMENT, url TEXT, 
                              method TEXT, param TEXT, param_type TEXT, timestamp TEXT)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_urls ON visited_urls(url)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_pages ON crawled_pages(url)''')
            self.conn.commit()
    
    def add_visited_url(self, url: str, depth: int = 0) -> bool:
        """Add URL to visited set if not already present"""
        with self.lock:
            try:
                self.conn.execute(
                    "INSERT OR IGNORE INTO visited_urls (url, timestamp, depth) VALUES (?, ?, ?)",
                    (url, datetime.now().isoformat(), depth)
                )
                self.conn.commit()
                return True
            except sqlite3.IntegrityError:
                return False  # URL already exists
    
    def is_visited(self, url: str) -> bool:
        """Check if URL has been visited"""
        with self.lock:
            cursor = self.conn.execute("SELECT 1 FROM visited_urls WHERE url = ?", (url,))
            return cursor.fetchone() is not None
    
    def get_visited_count(self) -> int:
        """Get total count of visited URLs"""
        with self.lock:
            cursor = self.conn.execute("SELECT COUNT(*) FROM visited_urls")
            return cursor.fetchone()[0]
    
    def add_crawled_page(self, url: str, content_hash: str, html_path: str, depth: int, status_code: int) -> int:
        """Add crawled page metadata to database"""
        with self.lock:
            cursor = self.conn.execute(
                "INSERT INTO crawled_pages (url, content_hash, html_path, timestamp, depth, status_code) VALUES (?, ?, ?, ?, ?, ?)",
                (url, content_hash, html_path, datetime.now().isoformat(), depth, status_code)
            )
            self.conn.commit()
            return cursor.lastrowid
    
    def get_crawled_pages_paginated(self, offset: int = 0, limit: int = 100) -> List[Dict[str, Any]]:
        """Get crawled pages with pagination for memory efficiency"""
        with self.lock:
            cursor = self.conn.execute(
                "SELECT url, content_hash, html_path, depth, status_code FROM crawled_pages LIMIT ? OFFSET ?",
                (limit, offset)
            )
            rows = cursor.fetchall()
            return [
                {
                    'url': row[0],
                    'hash': row[1],
                    'html_path': row[2],
                    'depth': row[3],
                    'status_code': row[4]
                }
                for row in rows
            ]
    
    def get_crawled_page_by_url(self, url: str) -> Optional[Dict[str, Any]]:
        """Get specific crawled page by URL"""
        with self.lock:
            cursor = self.conn.execute(
                "SELECT url, content_hash, html_path, depth, status_code FROM crawled_pages WHERE url = ?",
                (url,)
            )
            row = cursor.fetchone()
            if row:
                return {
                    'url': row[0],
                    'hash': row[1],
                    'html_path': row[2],
                    'depth': row[3],
                    'status_code': row[4]
                }
            return None
    
    def get_crawled_count(self) -> int:
        """Get total count of crawled pages"""
        with self.lock:
            cursor = self.conn.execute("SELECT COUNT(*) FROM crawled_pages")
            return cursor.fetchone()[0]
    
    def add_parameter(self, url: str, method: str, param: str, param_type: str) -> int:
        """Add parameter to database"""
        with self.lock:
            cursor = self.conn.execute(
                "INSERT INTO parameters (url, method, param, param_type, timestamp) VALUES (?, ?, ?, ?, ?)",
                (url, method, param, param_type, datetime.now().isoformat())
            )
            self.conn.commit()
            return cursor.lastrowid
    
    def get_parameters_paginated(self, offset: int = 0, limit: int = 100) -> List[Dict[str, Any]]:
        """Get parameters with pagination"""
        with self.lock:
            cursor = self.conn.execute(
                "SELECT url, method, param, param_type FROM parameters LIMIT ? OFFSET ?",
                (limit, offset)
            )
            rows = cursor.fetchall()
            return [
                {
                    'url': row[0],
                    'method': row[1],
                    'param': row[2],
                    'type': row[3]
                }
                for row in rows
            ]
    
    def get_parameters_count(self) -> int:
        """Get total count of parameters"""
        with self.lock:
            cursor = self.conn.execute("SELECT COUNT(*) FROM parameters")
            return cursor.fetchone()[0]
    
    def get_urls_by_depth(self, depth: int) -> List[str]:
        """Get all URLs at a specific depth"""
        with self.lock:
            cursor = self.conn.execute("SELECT url FROM visited_urls WHERE depth = ?", (depth,))
            return [row[0] for row in cursor.fetchall()]
    
    def cleanup_old_pages(self, max_age_hours: int = 24):
        """Remove crawled pages older than specified hours"""
        with self.lock:
            cutoff_time = (datetime.now() - timedelta(hours=max_age_hours)).isoformat()
            self.conn.execute(
                "DELETE FROM crawled_pages WHERE timestamp < ?",
                (cutoff_time,)
            )
            self.conn.commit()
    
    def get_storage_stats(self) -> Dict[str, Any]:
        """Get storage statistics"""
        with self.lock:
            visited_count = self.conn.execute("SELECT COUNT(*) FROM visited_urls").fetchone()[0]
            crawled_count = self.conn.execute("SELECT COUNT(*) FROM crawled_pages").fetchone()[0]
            param_count = self.conn.execute("SELECT COUNT(*) FROM parameters").fetchone()[0]
            
            # Get database file size
            db_size = os.path.getsize(self.db_path) if os.path.exists(self.db_path) else 0
            
            return {
                'visited_urls': visited_count,
                'crawled_pages': crawled_count,
                'parameters': param_count,
                'db_size_bytes': db_size,
                'db_size_mb': round(db_size / (1024 * 1024), 2)
            }
    
    def close(self):
        """Close database connection"""
        with self.lock:
            self.conn.close()


class DiskBasedVulnerabilityStorage:
    """
    Disk-based vulnerability storage with pagination for large-scale scanning.
    Replaces in-memory vulnerability lists with SQLite database for scalability.
    """

    def __init__(self, db_path='vulnerability_storage.db'):
        self.db_path = db_path
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.lock = threading.Lock()
        self._init_tables()

    def _init_tables(self):
        """Initialize database tables for vulnerability storage"""
        with self.lock:
            self.conn.execute('''CREATE TABLE IF NOT EXISTS vulnerabilities
                             (id INTEGER PRIMARY KEY AUTOINCREMENT, 
                              type TEXT, url TEXT, parameter TEXT, 
                              evidence TEXT, severity TEXT, confidence INTEGER,
                              cwe TEXT, timestamp TEXT, payload TEXT)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_vuln_type ON vulnerabilities(type)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_vuln_url ON vulnerabilities(url)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_vuln_severity ON vulnerabilities(severity)''')
            self.conn.commit()

    def add_vulnerability(self, vulnerability: Dict[str, Any]) -> int:
        """Add vulnerability to database"""
        with self.lock:
            cursor = self.conn.execute(
                """INSERT INTO vulnerabilities 
                   (type, url, parameter, evidence, severity, confidence, cwe, timestamp, payload)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    vulnerability.get('type', ''),
                    vulnerability.get('url', ''),
                    vulnerability.get('parameter', ''),
                    vulnerability.get('evidence', ''),
                    vulnerability.get('severity', ''),
                    vulnerability.get('confidence', 0),
                    vulnerability.get('cwe', ''),
                    datetime.now().isoformat(),
                    vulnerability.get('payload', '')
                )
            )
            self.conn.commit()
            return cursor.lastrowid

    def get_vulnerabilities_paginated(self, offset: int = 0, limit: int = 100) -> List[Dict[str, Any]]:
        """Get vulnerabilities with pagination for memory efficiency"""
        with self.lock:
            cursor = self.conn.execute(
                """SELECT type, url, parameter, evidence, severity, confidence, cwe, timestamp, payload
                   FROM vulnerabilities ORDER BY timestamp DESC LIMIT ? OFFSET ?""",
                (limit, offset)
            )
            rows = cursor.fetchall()
            return [
                {
                    'type': row[0],
                    'url': row[1],
                    'parameter': row[2],
                    'evidence': row[3],
                    'severity': row[4],
                    'confidence': row[5],
                    'cwe': row[6],
                    'timestamp': row[7],
                    'payload': row[8]
                }
                for row in rows
            ]

    def get_vulnerabilities_by_severity(self, severity: str) -> List[Dict[str, Any]]:
        """Get all vulnerabilities of a specific severity"""
        with self.lock:
            cursor = self.conn.execute(
                """SELECT type, url, parameter, evidence, severity, confidence, cwe, timestamp, payload
                   FROM vulnerabilities WHERE severity = ? ORDER BY timestamp DESC""",
                (severity,)
            )
            rows = cursor.fetchall()
            return [
                {
                    'type': row[0],
                    'url': row[1],
                    'parameter': row[2],
                    'evidence': row[3],
                    'severity': row[4],
                    'confidence': row[5],
                    'cwe': row[6],
                    'timestamp': row[7],
                    'payload': row[8]
                }
                for row in rows
            ]

    def get_vulnerabilities_by_type(self, vuln_type: str) -> List[Dict[str, Any]]:
        """Get all vulnerabilities of a specific type"""
        with self.lock:
            cursor = self.conn.execute(
                """SELECT type, url, parameter, evidence, severity, confidence, cwe, timestamp, payload
                   FROM vulnerabilities WHERE type = ? ORDER BY timestamp DESC""",
                (vuln_type,)
            )
            rows = cursor.fetchall()
            return [
                {
                    'type': row[0],
                    'url': row[1],
                    'parameter': row[2],
                    'evidence': row[3],
                    'severity': row[4],
                    'confidence': row[5],
                    'cwe': row[6],
                    'timestamp': row[7],
                    'payload': row[8]
                }
                for row in rows
            ]

    def get_vulnerability_count(self) -> int:
        """Get total count of vulnerabilities"""
        with self.lock:
            cursor = self.conn.execute("SELECT COUNT(*) FROM vulnerabilities")
            return cursor.fetchone()[0]

    def get_vulnerability_count_by_severity(self, severity: str) -> int:
        """Get count of vulnerabilities by severity"""
        with self.lock:
            cursor = self.conn.execute("SELECT COUNT(*) FROM vulnerabilities WHERE severity = ?", (severity,))
            return cursor.fetchone()[0]

    def cleanup_old_vulnerabilities(self, max_age_hours: int = 24):
        """Remove vulnerabilities older than specified hours"""
        with self.lock:
            cutoff_time = (datetime.now() - timedelta(hours=max_age_hours)).isoformat()
            cursor = self.conn.execute(
                "DELETE FROM vulnerabilities WHERE timestamp < ?",
                (cutoff_time,)
            )
            self.conn.commit()
            return cursor.rowcount

    def get_storage_stats(self) -> Dict[str, Any]:
        """Get storage statistics"""
        with self.lock:
            total_count = self.conn.execute("SELECT COUNT(*) FROM vulnerabilities").fetchone()[0]
            
            # Get counts by severity
            severity_counts = {}
            for severity in ['Critical', 'High', 'Medium', 'Low', 'Info']:
                count = self.conn.execute("SELECT COUNT(*) FROM vulnerabilities WHERE severity = ?", (severity,)).fetchone()[0]
                if count > 0:
                    severity_counts[severity] = count
            
            # Get database file size
            db_size = os.path.getsize(self.db_path) if os.path.exists(self.db_path) else 0
            
            return {
                'total_vulnerabilities': total_count,
                'by_severity': severity_counts,
                'db_size_bytes': db_size,
                'db_size_mb': round(db_size / (1024 * 1024), 2)
            }

    def get_all_vulnerabilities(self) -> List[Dict[str, Any]]:
        """Get all vulnerabilities (use with caution for large datasets)"""
        with self.lock:
            cursor = self.conn.execute(
                """SELECT type, url, parameter, evidence, severity, confidence, cwe, timestamp, payload
                   FROM vulnerabilities ORDER BY timestamp DESC"""
            )
            rows = cursor.fetchall()
            return [
                {
                    'type': row[0],
                    'url': row[1],
                    'parameter': row[2],
                    'evidence': row[3],
                    'severity': row[4],
                    'confidence': row[5],
                    'cwe': row[6],
                    'timestamp': row[7],
                    'payload': row[8]
                }
                for row in rows
            ]

    def clear_all_vulnerabilities(self):
        """Clear all vulnerabilities from database"""
        with self.lock:
            self.conn.execute("DELETE FROM vulnerabilities")
            self.conn.commit()

    def close(self):
        """Close database connection"""
        with self.lock:
            self.conn.close()


class SecondOrderInjectionQueue:
    """
    Persistent queue for delayed second-order injection verification.
    Stores injection points with TTL and supports background retry processing.
    """

    def __init__(self, db_path='second_order_queue.db', default_ttl=300):
        self.db_path = db_path
        self.default_ttl = default_ttl
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.lock = threading.Lock()
        self._init_tables()

    def _init_tables(self):
        """Initialize database tables for injection point queue"""
        with self.lock:
            self.conn.execute('''CREATE TABLE IF NOT EXISTS injection_queue
                             (id INTEGER PRIMARY KEY AUTOINCREMENT, 
                              url TEXT, 
                              referrer TEXT, 
                              cookies TEXT, 
                              headers TEXT, 
                              data TEXT, 
                              timestamp TEXT, 
                              ttl INTEGER,
                              retry_count INTEGER DEFAULT 0,
                              max_retries INTEGER DEFAULT 10,
                              status TEXT DEFAULT 'pending',
                              last_retry TEXT)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_queue_status ON injection_queue(status)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_queue_timestamp ON injection_queue(timestamp)''')
            self.conn.execute('''CREATE INDEX IF NOT EXISTS idx_queue_status_timestamp ON injection_queue(status, timestamp)''')
            self.conn.commit()

    def add_injection_point(self, injection_point: Dict[str, Any], ttl: int = None) -> int:
        """Add injection point to queue for delayed verification"""
        with self.lock:
            ttl = ttl or self.default_ttl
            cursor = self.conn.execute(
                """INSERT INTO injection_queue 
                   (url, referrer, cookies, headers, data, timestamp, ttl, retry_count, max_retries, status)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    injection_point.get('url', ''),
                    injection_point.get('referrer', ''),
                    json.dumps(injection_point.get('cookies', {})),
                    json.dumps(injection_point.get('headers', {})),
                    json.dumps(injection_point.get('data', {})),
                    datetime.fromtimestamp(injection_point.get('timestamp', time.time())).isoformat(),
                    ttl,
                    0,
                    10,  # Default max retries
                    'pending'
                )
            )
            self.conn.commit()
            return cursor.lastrowid

    def get_pending_injection_points(self, limit: int = 100) -> List[Dict[str, Any]]:
        """Get pending injection points for verification"""
        with self.lock:
            current_time = datetime.now()
            cursor = self.conn.execute(
                """SELECT id, url, referrer, cookies, headers, data, timestamp, ttl, retry_count, max_retries, last_retry
                   FROM injection_queue 
                   WHERE status = 'pending' AND retry_count < max_retries
                   ORDER BY timestamp ASC 
                   LIMIT ?""",
                (limit,)
            )
            rows = cursor.fetchall()
            injection_points = []
            for row in rows:
                try:
                    injection_points.append({
                        'id': row[0],
                        'url': row[1],
                        'referrer': row[2],
                        'cookies': json.loads(row[3]) if row[3] else {},
                        'headers': json.loads(row[4]) if row[4] else {},
                        'data': json.loads(row[5]) if row[5] else {},
                        'timestamp': row[6],
                        'ttl': row[7],
                        'retry_count': row[8],
                        'max_retries': row[9],
                        'last_retry': row[10]
                    })
                except json.JSONDecodeError:
                    logging.warning(f"Failed to parse injection point data for ID {row[0]}")
                    continue
            return injection_points

    def update_retry_count(self, injection_id: int, success: bool = False):
        """Update retry count and status for an injection point"""
        with self.lock:
            if success:
                self.conn.execute(
                    "UPDATE injection_queue SET status = 'verified', last_retry = ? WHERE id = ?",
                    (datetime.now().isoformat(), injection_id)
                )
            else:
                self.conn.execute(
                    "UPDATE injection_queue SET retry_count = retry_count + 1, last_retry = ? WHERE id = ?",
                    (datetime.now().isoformat(), injection_id)
                )
            self.conn.commit()

    def cleanup_expired_injection_points(self):
        """Remove expired injection points based on TTL"""
        with self.lock:
            current_time = datetime.now()
            cursor = self.conn.execute(
                """SELECT id, timestamp, ttl FROM injection_queue WHERE status = 'pending'"""
            )
            rows = cursor.fetchall()
            expired_ids = []
            for row in rows:
                try:
                    injection_time = datetime.fromisoformat(row[1])
                    ttl_seconds = row[2]
                    if (current_time - injection_time).total_seconds() > ttl_seconds:
                        expired_ids.append(row[0])
                except (ValueError, TypeError):
                    continue
            
            if expired_ids:
                cursor = self.conn.execute(
                    f"DELETE FROM injection_queue WHERE id IN ({','.join(['?'] * len(expired_ids))})",
                    expired_ids
                )
                self.conn.commit()
                logging.info(f"Cleaned up {len(expired_ids)} expired injection points from queue")
                return len(expired_ids)
            return 0

    def get_queue_stats(self) -> Dict[str, Any]:
        """Get queue statistics"""
        with self.lock:
            total_count = self.conn.execute("SELECT COUNT(*) FROM injection_queue").fetchone()[0]
            pending_count = self.conn.execute("SELECT COUNT(*) FROM injection_queue WHERE status = 'pending'").fetchone()[0]
            verified_count = self.conn.execute("SELECT COUNT(*) FROM injection_queue WHERE status = 'verified'").fetchone()[0]
            failed_count = self.conn.execute("SELECT COUNT(*) FROM injection_queue WHERE retry_count >= max_retries").fetchone()[0]
            
            return {
                'total_injection_points': total_count,
                'pending': pending_count,
                'verified': verified_count,
                'failed': failed_count
            }

    def clear_queue(self):
        """Clear all injection points from queue"""
        with self.lock:
            self.conn.execute("DELETE FROM injection_queue")
            self.conn.commit()

    def close(self):
        """Close database connection"""
        with self.lock:
            self.conn.close()


class CrawlerEngine:
    def __init__(self, target: str, config: Dict[str, Any], base_domain: str, exclusion_patterns: List[str], circuit_breaker: CircuitBreaker) -> None:
        self.target = target
        self.config = config
        self.base_domain = base_domain
        self.exclusion_patterns = exclusion_patterns
        self.circuit_breaker = circuit_breaker
        
        # Replace in-memory storage with disk-based pagination
        use_disk_storage = config.get('use_disk_storage', True)
        if use_disk_storage:
            storage_db = config.get('storage_db', 'url_storage.db')
            self.url_storage = DiskBasedURLStorage(storage_db)
            # Maintain small in-memory cache for frequently accessed URLs
            self.visited_urls_cache: Set[str] = set()
            self.crawled_pages_cache: List[Dict[str, Any]] = []
            self.parameters_cache: List[Dict[str, Any]] = []
            # For compatibility with existing code, provide lightweight wrappers
            self.visited_urls = self.visited_urls_cache
            self.crawled_pages = self.crawled_pages_cache
            self.parameters = self.parameters_cache
        else:
            # Fallback to in-memory storage for small scans
            self.url_storage = None
            self.visited_urls: Set[str] = set()
            self.crawled_pages: List[Dict[str, Any]] = []
            self.parameters: List[Dict[str, Any]] = []
        
        self.use_disk_storage = use_disk_storage
        self.stop_event = asyncio.Event()
        
        # FP handling configuration
        fp_config = config.get('fp_handling', {})
        self.context_specific_whitelist = fp_config.get('context_specific_whitelist', True)
    
    def _add_to_visited(self, url: str, depth: int = 0) -> bool:
        """Add URL to visited storage (disk or memory)"""
        if self.use_disk_storage and self.url_storage:
            added = self.url_storage.add_visited_url(url, depth)
            if added:
                # Also add to cache for quick access
                if len(self.visited_urls_cache) < 1000:
                    self.visited_urls_cache.add(url)
            return added
        else:
            if url not in self.visited_urls:
                self.visited_urls.add(url)
                return True
            return False
    
    def _is_url_visited(self, url: str) -> bool:
        """Check if URL is visited (disk or memory)"""
        if self.use_disk_storage and self.url_storage:
            # Check cache first
            if url in self.visited_urls_cache:
                return True
            # Check disk storage
            return self.url_storage.is_visited(url)
        else:
            return url in self.visited_urls
    
    def _add_crawled_page(self, url: str, html: str, depth: int, status_code: int) -> None:
        """Add crawled page to storage (disk or memory)"""
        if self.use_disk_storage and self.url_storage:
            # Store HTML content to disk to save memory
            html_path = f"html_cache/{hashlib.md5(url.encode()).hexdigest()}.html"
            os.makedirs(os.path.dirname(html_path), exist_ok=True)
            with open(html_path, 'w', encoding='utf-8') as f:
                f.write(html)
            
            content_hash = hashlib.md5(html.encode()).hexdigest()
            self.url_storage.add_crawled_page(url, content_hash, html_path, depth, status_code)
            
            # Keep small cache of recent pages with metadata only (no HTML)
            if len(self.crawled_pages_cache) < 100:
                self.crawled_pages_cache.append({
                    'url': url,
                    'html_path': html_path,
                    'depth': depth,
                    'status_code': status_code
                })
        else:
            # Even in in-memory mode, store HTML to disk to be consistent
            html_path = f"html_cache/{hashlib.md5(url.encode()).hexdigest()}.html"
            os.makedirs(os.path.dirname(html_path), exist_ok=True)
            with open(html_path, 'w', encoding='utf-8') as f:
                f.write(html)
            
            content_hash = hashlib.md5(html.encode()).hexdigest()
            self.crawled_pages.append({
                'url': url,
                'html_path': html_path,
                'depth': depth,
                'status_code': status_code
            })
    
    def _get_html_content(self, url: str) -> Optional[str]:
        """Retrieve HTML content for a crawled page from disk"""
        html_path = f"html_cache/{hashlib.md5(url.encode()).hexdigest()}.html"
        try:
            with open(html_path, 'r', encoding='utf-8') as f:
                return f.read()
        except (FileNotFoundError, IOError):
            return None
    
    def _get_crawled_pages_iterator(self):
        """Get iterator over crawled pages (handles pagination for disk storage)"""
        if self.use_disk_storage and self.url_storage:
            # Return paginated iterator for disk storage
            offset = 0
            limit = 100
            while True:
                pages = self.url_storage.get_crawled_pages_paginated(offset, limit)
                if not pages:
                    break
                for page in pages:
                    # Load HTML content from disk on demand
                    html_content = self._get_html_content(page['url'])
                    page['html'] = html_content if html_content else ''
                    yield page
                offset += limit
        else:
            # Return simple iterator for memory storage with HTML loading
            for page in self.crawled_pages:
                # Load HTML from disk if needed
                if 'html_path' in page and not page.get('html'):
                    html_content = self._get_html_content(page['url'])
                    page['html'] = html_content if html_content else ''
                elif not page.get('html'):
                    page['html'] = ''
                yield page
    
    def _add_parameter(self, url: str, method: str, param: str, param_type: str) -> None:
        """Add parameter to storage (disk or memory)"""
        if self.use_disk_storage and self.url_storage:
            self.url_storage.add_parameter(url, method, param, param_type)
            # Keep small cache
            if len(self.parameters_cache) < 100:
                self.parameters_cache.append({
                    'url': url,
                    'method': method,
                    'param': param,
                    'type': param_type
                })
        else:
            if not any(p['url'] == url and p['method'] == method and p['param'] == param for p in self.parameters):
                self.parameters.append({
                    'url': url,
                    'method': method,
                    'param': param,
                    'type': param_type
                })
    
    def _get_parameters_iterator(self):
        """Get iterator over parameters (handles pagination for disk storage)"""
        if self.use_disk_storage and self.url_storage:
            offset = 0
            limit = 100
            while True:
                params = self.url_storage.get_parameters_paginated(offset, limit)
                if not params:
                    break
                for param in params:
                    yield param
                offset += limit
        else:
            for param in self.parameters:
                yield param
    
    def get_storage_stats(self) -> Dict[str, Any]:
        """Get storage statistics"""
        if self.use_disk_storage and self.url_storage:
            return self.url_storage.get_storage_stats()
        else:
            return {
                'visited_urls': len(self.visited_urls),
                'crawled_pages': len(self.crawled_pages),
                'parameters': len(self.parameters),
                'storage_type': 'memory',
                'estimated_memory_mb': round(
                    (len(self.visited_urls) * 100 + 
                     len(self.crawled_pages) * 50000 + 
                     len(self.parameters) * 200) / (1024 * 1024), 2
                )
            }
    def _is_valid_url(self, url: str) -> bool:
        try:
            p = urlparse(url)
            if not p.scheme or not p.netloc:
                return False
            if p.scheme not in ('http', 'https'):
                return False
            if OOB_MARKER in url or OOB_DNS in url or 'evil.com' in url:
                return False
            if p.netloc in ('localhost', '127.0.0.1', '::1') or p.netloc.startswith('127.'):
                return False
            if re.search(r'[^a-zA-Z0-9.\-:_]', p.netloc):
                return False
            
            # Filter out JavaScript code fragments and invalid patterns
            # Check for common JavaScript patterns that shouldn't be URLs
            js_patterns = [
                r'\.',          # Contains dots that look like JS property access
                r',',           # Contains commas (JS code)
                r'\(',          # Contains parentheses (JS function calls)
                r'\)',          # Contains parentheses (JS function calls)
                r'\{',          # Contains braces (JS objects)
                r'\}',          # Contains braces (JS objects)
                r';',           # Contains semicolons (JS statements)
                r'\+',          # Contains plus signs (JS operators)
                r'=',           # Contains equals signs (JS assignments) - more specific check needed
                r'\s',          # Contains whitespace (JS code)
            ]
            
            # Check path for JavaScript code patterns
            if p.path:
                # Allow paths with dots (like .js, .css) but not property access patterns
                if re.search(r'\.\w+[.,;+\)\(\{\}]', p.path):
                    return False
                # Filter out obvious JavaScript code
                if any(char in p.path for char in ',;(){}+'):
                    return False
                # Check for common JS method call patterns
                if re.search(r'\w+\.\w+\(', p.path):
                    return False
                # Check for assignment patterns
                if re.search(r'\w+\s*=\s*\w+', p.path):
                    return False
            
            # Check query string for JavaScript code
            if p.query:
                if any(char in p.query for char in ',;(){}+'):
                    return False
                if re.search(r'\w+\.\w+\(', p.query):
                    return False
            
            return True
        except Exception:
            return False
    def _is_in_scope(self, url: str) -> bool:
        if not self._is_valid_url(url):
            return False
        p = urlparse(url)
        return p.netloc == self.base_domain and p.scheme in ('http', 'https')
    def _extract_links(self, soup: Any, base_url: str, html: str) -> List[str]:
        links = set()
        for a in soup.find_all('a', href=True):
            abs_url = urljoin(base_url, a['href'])
            if self._is_in_scope(abs_url): links.add(abs_url)
        for form in soup.find_all('form'):
            action = form.get('action', '')
            if action:
                abs_url = urljoin(base_url, action)
                if self._is_in_scope(abs_url): links.add(abs_url)
        for link in soup.find_all('link', href=True):
            abs_url = urljoin(base_url, link['href'])
            if self._is_in_scope(abs_url): links.add(abs_url)
        for script in soup.find_all('script', src=True):
            abs_url = urljoin(base_url, script['src'])
            if self._is_in_scope(abs_url): links.add(abs_url)
        for img in soup.find_all('img', src=True):
            abs_url = urljoin(base_url, img['src'])
            if self._is_in_scope(abs_url): links.add(abs_url)
        for tag in soup.find_all(attrs={"srcset": True}):
            for part in tag['srcset'].split(','):
                candidate = part.strip().split(' ')[0]
                abs_url = urljoin(base_url, candidate)
                if self._is_in_scope(abs_url): links.add(abs_url)
        for tag in soup.find_all(attrs={"data-url": True}):
            abs_url = urljoin(base_url, tag['data-url'])
            if self._is_in_scope(abs_url): links.add(abs_url)
        for meta in soup.find_all('meta', attrs={"http-equiv": "refresh", "content": True}):
            match = re.search(r'url=([^;]+)', meta['content'], re.I)
            if match:
                abs_url = urljoin(base_url, match.group(1))
                if self._is_in_scope(abs_url): links.add(abs_url)
        # More careful JavaScript URL extraction to avoid code fragments
        js_pattern = re.findall(r'''(?:href=|location\.href=|window\.open\(['"]|fetch\(['"]|src=|action=|url:['"])([^'")\s,;{}()]+)''', html, re.I)
        for m in js_pattern:
            m = m.strip('"\'')
            # Additional validation to filter out JavaScript code
            if m and not re.search(r'[,.:;{}\(\)\+\=\*\!]', m):
                # Must look like a URL (contain / or start with http/https or be a relative path)
                if '/' in m or m.startswith('http') or m.startswith('./') or m.startswith('../') or m.startswith('?'):
                    abs_url = urljoin(base_url, m)
                    if self._is_in_scope(abs_url): links.add(abs_url)
        return list(links)
    def _extract_parameters(self, url: str, html: str, soup: Any) -> None:
        parsed = urlparse(url)
        for param in parse_qs(parsed.query):
            self._add_param(url, 'GET', param, 'query')
        for form in soup.find_all('form'):
            method = form.get('method', 'get').upper()
            action = urljoin(url, form.get('action', '')) or url
            for inp in form.find_all(['input', 'textarea', 'select']):
                name = inp.get('name')
                if name:
                    self._add_param(action, method, name, 'post')
            if form.get('enctype') == 'application/json':
                for inp in form.find_all(['input', 'textarea', 'select']):
                    name = inp.get('name')
                    if name:
                        self._add_param(action, 'POST', name, 'json')
        json_keys = re.findall(r'''['"](\w+)['"]\s*:\s*['"]?\{.*?\}['"]?''', html)
        for key in json_keys:
            self._add_param(url, 'POST', key, 'json')
    def _add_param(self, url: str, method: str, param: str, ptype: str) -> None:
        # Context-specific whitelist: Skip parameters from static resources (if enabled)
        if self.context_specific_whitelist:
            from urllib.parse import urlparse
            parsed_url = urlparse(url)
            url_path = parsed_url.path.lower()
            
            # Skip if URL path contains /static/
            if '/static/' in url_path:
                return
            
            # Skip if URL ends with .css
            if url_path.endswith('.css'):
                return
        
        if not any(p['url']==url and p['method']==method and p['param']==param for p in self.parameters):
            self.parameters.append({'url':url,'method':method,'param':param,'type':ptype})

    def close(self):
        """Close database connection to prevent resource leaks."""
        if self.use_disk_storage and self.url_storage:
            try:
                self.url_storage.close()
                logging.info("CrawlerEngine: Disk-based URL storage closed")
            except Exception as e:
                logging.warning(f"Error closing URL storage in CrawlerEngine: {e}")

# ---------------------------------------------------------------------
# SESSION MANAGER
# ---------------------------------------------------------------------
class SessionManager:
    def __init__(self, config: Dict[str, Any], loop: asyncio.AbstractEventLoop, circuit_breaker: CircuitBreaker, target: str = None) -> None:
        self.config = config
        self.loop = loop
        self.circuit_breaker = circuit_breaker
        self.target = target
        self.async_session: Optional[AsyncSession] = None
        self.secondary_session: Optional[AsyncSession] = None
        
        # Initialize global request cache with LRU + TTL
        cache_config = config.get('request_cache', {})
        self.request_cache = BaselineCache(
            max_size=cache_config.get('max_size', 1000),
            default_ttl=cache_config.get('default_ttl', 300),  # 5 minutes default
            use_disk_storage=cache_config.get('use_disk_storage', False),
            db_path=cache_config.get('db_path', 'baseline_cache.db')
        )
        self.cache_enabled = cache_config.get('enabled', True)
        
        # Initialize request deduplicator to avoid redundant tests
        dedup_config = config.get('request_deduplication', {})
        self.request_deduplicator = RequestDeduplicator(dedup_config)
        
        # Initialize HTTP/2 and HTTP/3 clients
        self.http2_client = HTTP2Client(config)
        self.http3_client = HTTP3Client(config)
        
        # Initialize traffic shaper with configuration
        traffic_shaper_config = config.get('traffic_shaping', {})
        self.traffic_shaper = TrafficShaper(
            enabled=traffic_shaper_config.get('enabled', True),
            randomize_interval=traffic_shaper_config.get('randomize_interval', True),
            randomize_headers=traffic_shaper_config.get('randomize_headers', True),
            randomize_case=traffic_shaper_config.get('randomize_case', True),
            browser_simulation=traffic_shaper_config.get('browser_simulation', True)
        )
        
        # Initialize IDS/IPS rate limiter with configuration
        ids_ips_config = config.get('ids_ips_throttling', {})
        self.rate_limiter = AsyncRateLimiter(
            config.get('delay', DEFAULT_DELAY), 
            traffic_shaper=self.traffic_shaper,
            ids_ips_config=ids_ips_config if ids_ips_config else None
        )
        
        # Support both legacy proxy_list and new proxy_pool configuration
        proxy_config = config.get('proxy_pool', {})
        if proxy_config:
            # New proxy pool configuration
            self.proxy_pool = ProxyPool(
                enable_rotation=proxy_config.get('enable_rotation', True),
                rotation_interval=proxy_config.get('rotation_interval', 100),
                health_check_interval=proxy_config.get('health_check_interval', 300),
                prefer_geo_diverse=proxy_config.get('prefer_geo_diverse', True),
                max_failure_rate=proxy_config.get('max_failure_rate', 0.5),
                target_url=self.target
            )
            
            # Configure auto-healing
            self.proxy_pool.auto_healing_enabled = proxy_config.get('auto_healing_enabled', True)
            
            # Configure sticky session
            self.proxy_pool.sticky_session_enabled = proxy_config.get('sticky_session_enabled', False)
            if proxy_config.get('sticky_session_duration'):
                self.proxy_pool.sticky_session_duration = proxy_config.get('sticky_session_duration')
            
            # Add proxies from configuration
            proxies = proxy_config.get('proxies', [])
            for proxy in proxies:
                if isinstance(proxy, str):
                    # Simple proxy string (legacy format)
                    self.proxy_pool.add_proxy_url(proxy, target_url=self.target)
                elif isinstance(proxy, dict):
                    # Detailed proxy configuration
                    self.proxy_pool.add_proxy(ProxyConfig(
                        proxy_url=proxy.get('url'),
                        proxy_type=proxy.get('type', 'http'),
                        username=proxy.get('username'),
                        password=proxy.get('password'),
                        country=proxy.get('country'),
                        region=proxy.get('region'),
                        is_residential=proxy.get('is_residential', False),
                        health_check_url=proxy.get('health_check_url'),
                        target_url=self.target
                    ))
            
            # Keep legacy proxy_rotator for backward compatibility
            self.proxy_rotator = ProxyRotator(config.get('proxy_list'))
        else:
            # Legacy proxy list support
            self.proxy_pool = None
            self.proxy_rotator = ProxyRotator(config.get('proxy_list'))
        
    async def setup(self) -> None:
        user_agent = self.config.get('user_agent')
        if user_agent:
            user_agent_rotator = UserAgentRotator(user_agents=[user_agent])
        else:
            user_agent_rotator = None
        self.async_session = AsyncSession(
            loop=self.loop, 
            proxy_pool=self.proxy_pool,
            user_agent_rotator=user_agent_rotator,
            traffic_shaper=self.traffic_shaper,
            rate_limiter=self.rate_limiter,
            config=self.config
        )
    async def close(self) -> None:
        if self.async_session:
            await self.async_session.close()
        # Clean up cache
        await self.request_cache.clear()
    
    async def get_cache_stats(self) -> Dict[str, Any]:
        """Get request cache statistics."""
        return self.request_cache.get_stats()
    
    async def cleanup_cache(self) -> int:
        """Clean up expired cache entries. Returns number of entries removed."""
        return await self.request_cache.cleanup_expired()
    async def fetch(self, url: str, method: str = 'GET', data: Optional[Dict[str, Any]] = None, json_data: Optional[Dict[str, Any]] = None, headers: Optional[Dict[str, str]] = None, allow_redirects: bool = True, use_cache: bool = True, session_manager: SessionStateManager = None, session_id: str = None, cookies: Optional[Dict[str, str]] = None) -> Optional[Any]:
        """
        Fetch URL with optional caching support and CSRF token extraction.
        
        Args:
            url: Target URL
            method: HTTP method
            data: POST data
            json_data: JSON data
            headers: HTTP headers
            allow_redirects: Whether to follow redirects
            use_cache: Whether to use request cache (default: True)
            session_manager: Optional SessionStateManager for CSRF token handling
            session_id: Optional session ID for CSRF token storage
            cookies: Optional cookies dict
        
        Returns:
            Response object or None if failed
        """
        # If session_manager is provided and this is a POST request, extract CSRF tokens first
        if session_manager and session_id and method.upper() == 'POST':
            # Check if CSRF tokens are already cached to avoid unnecessary GET requests
            tokens_cached = await session_manager.has_csrf_tokens(session_id, url)
            
            if not tokens_cached:
                # Extract CSRF tokens from the page before submitting POST (only if not cached)
                try:
                    get_resp = await self.async_session.request('GET', url, allow_redirects=False, 
                        timeout=ClientTimeout(total=DEFAULT_REQUEST_TIMEOUT, connect=DEFAULT_CONNECT_TIMEOUT, sock_read=DEFAULT_SOCK_READ_TIMEOUT))
                    if get_resp and get_resp.status == 200:
                        html = await get_resp.text()
                        await session_manager.extract_csrf_tokens_from_html(session_id, url, html)
                        logging.debug(f"[CSRF] Fetched and extracted CSRF tokens for {url}")
                except Exception as e:
                    logging.warning(f"[CSRF] Error extracting CSRF tokens before POST: {e}")
            else:
                logging.debug(f"[CSRF] Using cached CSRF tokens for {url}")
            
            # Inject CSRF tokens into the POST data (from cache or freshly extracted)
            csrf_field_names = [
                'csrf_token', 'csrfmiddlewaretoken', '_token', 'authenticity_token',
                'form_build_id', 'form_token', 'security_token', 'anti_csrf_token'
            ]
            
            if data and isinstance(data, dict):
                for field_name in csrf_field_names:
                    token_value = await session_manager.get_csrf_token(session_id, url, field_name)
                    if token_value and field_name not in data:
                        data[field_name] = token_value
                        logging.debug(f"[CSRF] Injected {field_name} into POST request to {url}")
            elif json_data and isinstance(json_data, dict):
                for field_name in csrf_field_names:
                    token_value = await session_manager.get_csrf_token(session_id, url, field_name)
                    if token_value and field_name not in json_data:
                        json_data[field_name] = token_value
                        logging.debug(f"[CSRF] Injected {field_name} into JSON POST request to {url}")

        # Check request deduplication to avoid redundant tests
        if hasattr(self, 'request_deduplicator') and self.request_deduplicator:
            if self.request_deduplicator.is_duplicate_request(method, url, headers, data or json_data):
                logging.debug(f"Duplicate request skipped via deduplicator: {method} {url}")
                return None
        
        # Create cache key from request parameters
        import hashlib
        cache_key_parts = [method, url, str(data), str(json_data), str(headers)]
        cache_key = hashlib.md5('|'.join(cache_key_parts).encode()).hexdigest()
        
        # Check cache first if enabled and this is a safe-to-cache request
        if self.cache_enabled and use_cache and method == 'GET' and not data and not json_data:
            cached_response = await self.request_cache.get(cache_key)
            if cached_response:
                logging.debug(f"Cache HIT for {method} {url}")
                return CachedResponse(cached_response)
        
        if not self.circuit_breaker.allow_request():
            logging.warning(f"Circuit breaker is open, skipping request to {url}")
            return None
        
        kwargs = {'allow_redirects': allow_redirects}
        if headers: kwargs['headers'] = headers
        if data: kwargs['data'] = data
        if json_data: kwargs['json'] = json_data
        if cookies: kwargs['cookies'] = cookies
        # Add timeout for slow/unresponsive servers
        kwargs['timeout'] = ClientTimeout(total=DEFAULT_REQUEST_TIMEOUT, connect=DEFAULT_CONNECT_TIMEOUT, sock_read=DEFAULT_SOCK_READ_TIMEOUT)
        
        # Proxy handling - AsyncSession now handles proxy pool internally
        # Only use legacy proxy_rotator if proxy_pool is not available
        proxy = None
        if not self.proxy_pool:
            proxy = self.proxy_rotator.get_next_proxy()
            if proxy:
                kwargs['proxy'] = proxy
        
        # Try HTTP/2 if enabled and available
        if hasattr(self, 'http2_client') and self.http2_client and self.http2_client.enabled:
            try:
                http2_response = await self.http2_client.make_request(method, url, headers, data or json_data)
                if http2_response:
                    logging.debug(f"HTTP/2 request successful: {method} {url}")
                    # Convert HTTP/2 response to standard format
                    return http2_response
            except Exception as e:
                logging.debug(f"HTTP/2 request failed, falling back to HTTP/1.1: {e}")
        
        # Try HTTP/3 if enabled and available
        if hasattr(self, 'http3_client') and self.http3_client and self.http3_client.is_available():
            try:
                http3_response = await self.http3_client.make_request(method, url, headers, data or json_data)
                if http3_response:
                    logging.debug(f"HTTP/3 request successful: {method} {url}")
                    return http3_response
            except Exception as e:
                logging.debug(f"HTTP/3 request failed, falling back to HTTP/1.1: {e}")
                
        for attempt in range(self.circuit_breaker.max_retries):
            try:
                resp = await self.async_session.request(method, url, **kwargs)
                self.circuit_breaker.record_success()
                
                # Extract CSRF tokens from GET responses for future use
                response_text = None
                if session_manager and session_id and method.upper() == 'GET' and resp and resp.status == 200:
                    try:
                        response_text = await resp.text()
                        session_manager.extract_csrf_tokens_from_html(session_id, url, response_text)
                    except Exception as e:
                        logging.debug(f"[CSRF] Error extracting CSRF tokens from GET response: {e}")

                # Cache successful GET requests without body
                if self.cache_enabled and use_cache and method == 'GET' and not data and not json_data and resp:
                    # Extract only pickle-able data from response
                    try:
                        # Get response text if not already retrieved
                        if response_text is None:
                            try:
                                response_text = await resp.text()
                            except:
                                # If text can't be read, skip caching
                                response_text = None
                        
                        if response_text is not None:
                            cached_data = {
                                'status': resp.status,
                                'headers': dict(resp.headers),
                                'text': response_text,
                                'reason': resp.reason if hasattr(resp, 'reason') else None
                            }
                            await self.request_cache.set(cache_key, cached_data)
                            logging.debug(f"Cache SET for {method} {url}")
                    except Exception as cache_error:
                        logging.debug(f"Failed to cache response: {cache_error}")
                
                return resp
            except asyncio.TimeoutError as e:
                logging.warning(f"Timeout error {url} (attempt {attempt + 1}/{self.circuit_breaker.max_retries}): {e}")
                if attempt < self.circuit_breaker.max_retries - 1:
                    backoff_delay = self.circuit_breaker.get_backoff_delay(attempt)
                    logging.info(f"Retrying in {backoff_delay}s due to timeout...")
                    await asyncio.sleep(backoff_delay)
                else:
                    self.circuit_breaker.record_failure()
                    if proxy:
                        self.proxy_rotator.mark_failed(proxy)
                    logging.error(f"Max retries reached for {url} due to timeout")
            except Exception as e:
                logging.warning(f"Fetch error {url} (attempt {attempt + 1}/{self.circuit_breaker.max_retries}): {e}")
                if attempt < self.circuit_breaker.max_retries - 1:
                    backoff_delay = self.circuit_breaker.get_backoff_delay(attempt)
                    logging.info(f"Retrying in {backoff_delay}s...")
                    await asyncio.sleep(backoff_delay)
                else:
                    self.circuit_breaker.record_failure()
                    if proxy:
                        self.proxy_rotator.mark_failed(proxy)
        return None
    async def perform_browser_behavior(self, url: str) -> None:
        """Execute browser-like behavior requests (favicon, prefetch, etc.)"""
        if not self.traffic_shaper.enabled or not self.traffic_shaper.browser_simulation:
            return
            
        actions = self.traffic_shaper.get_browser_behavior_actions(url)
        for action in actions:
            try:
                # These are background requests, don't wait too long
                if action['type'] in ['favicon', 'prefetch', 'resource']:
                    await asyncio.sleep(random.uniform(0.1, 0.5))  # Small delay between browser actions
                    await self.fetch(
                        action['url'], 
                        method=action['method'],
                        headers=action['headers'],
                        allow_redirects=True
                    )
            except Exception as e:
                # Browser behavior failures shouldn't stop the scan
                logging.debug(f"Browser behavior action failed: {e}")
    
    async def get_throttle_status(self) -> dict:
        """
        Get current IDS/IPS throttling status for monitoring.
        
        Returns:
            dict: Status information including rates, tokens, etc.
        """
        return await self.rate_limiter.get_throttle_status()

    async def perform_authentication(self, auth_steps: List[Dict[str, Any]]) -> Optional[Dict[str, str]]:
        for step in auth_steps:
            url = step.get('url')
            method = step.get('method', 'GET')
            data = step.get('data')
            json_data = step.get('json')
            headers = step.get('headers', {})
            try:
                resp = await self.fetch(url, method=method, data=data, json_data=json_data, headers=headers)
                if resp and resp.status == 200:
                    logging.info(f"Authentication step succeeded: {method} {url}")
                else:
                    logging.warning(f"Authentication step failed: {method} {url} - Status: {resp.status if resp else 'No response'}")
            except Exception as e:
                logging.warning(f"Authentication error: {e}")
    def load_cookies(self, cookies):
        if self.async_session:
            for cookie in cookies:
                self.async_session.session.cookie_jar.update_cookies(cookie)

# ---------------------------------------------------------------------
# OOB MANAGER
# ---------------------------------------------------------------------
class OOBManager:
    def __init__(self, config: Dict[str, Any], public_ip: str) -> None:
        self.config = config
        self.public_ip = public_ip
        self.oob_server: Optional[Any] = None
        self.oob_port: Optional[int] = None
        self.oob_dns_ip = config.get('oob_dns_ip')
        self.oob_dns_domain = config.get('oob_dns_domain', 'oob.example.com')
        self.oob_marker_base = uuid.uuid4().hex[:8]
        self.enable_advanced_oob = config.get('enable_advanced_oob', False)
        self.smtp_oob_handler: Optional[Any] = None
        self.dns_oob_listener: Optional[Any] = None  # Replaces ICMP listener
        self.dns_oob_port: Optional[int] = None  # Track actual DNS port used (may differ from default)
        self.icmp_oob_listener: Optional[ICMPOOBListener] = None  # ICMP listener (requires root)
        self.enable_icmp_oob = config.get('enable_icmp_oob', False)  # Disabled by default
        self.https_oob_server: Optional[Any] = None
        self.https_oob_port: Optional[int] = None
        self.cleanup_thread: Optional[threading.Thread] = None
        self.cleanup_stop_event = threading.Event()
    async def setup(self) -> None:
        try:
            self.oob_server, self.oob_port = start_oob_server()
            logging.info(f"OOB HTTP: {self.public_ip}:{self.oob_port}")
        except Exception as e:
            logging.error(f"Failed to start OOB server: {e}")
            self.oob_server = None
            self.oob_port = None
        
        # Start cleanup thread for expired markers
        self.cleanup_stop_event.clear()
        self.cleanup_thread = threading.Thread(target=self._cleanup_loop, daemon=True)
        self.cleanup_thread.start()
        logging.info("OOB marker cleanup thread started")
        
        if self.enable_advanced_oob:
            self.smtp_oob_handler = SMTPOOBHandler()
            if self.smtp_oob_handler.start():
                logging.info("SMTP OOB server started on port 2525")
            
            # Use DNS listener instead of ICMP (no root required)
            self.dns_oob_listener = DNSOOBListener()
            if self.dns_oob_listener.start():
                self.dns_oob_port = self.dns_oob_listener.get_port()
                logging.info(f"DNS OOB listener started on port {self.dns_oob_port}")
            
            # ICMP OOB listener (optional, requires root privileges)
            if self.enable_icmp_oob:
                self.icmp_oob_listener = ICMPOOBListener(self.public_ip)
                if self.icmp_oob_listener.start_listener():
                    logging.info("ICMP OOB listener started (requires root privileges)")
                else:
                    logging.warning("Failed to start ICMP OOB listener - requires root privileges")
                    self.icmp_oob_listener = None
            
            try:
                self.https_oob_server, self.https_oob_port = start_https_oob_server()
                if self.https_oob_server:
                    logging.info(f"OOB HTTPS: {self.public_ip}:{self.https_oob_port}")
            except Exception as e:
                logging.error(f"Failed to start HTTPS OOB server: {e}")
                self.https_oob_server = None
                self.https_oob_port = None
    
    def _cleanup_loop(self):
        """Background thread to clean up expired markers"""
        while not self.cleanup_stop_event.is_set():
            try:
                cleanup_expired_markers()
                self.cleanup_stop_event.wait(timeout=DEFAULT_HEALTH_CHECK_TIMEOUT)  # Check every 5 seconds
            except Exception as e:
                logging.warning(f"OOB cleanup thread error: {e}")
    def stop(self) -> None:
        # Stop cleanup thread
        if self.cleanup_thread:
            self.cleanup_stop_event.set()
            self.cleanup_thread.join(timeout=2)
            logging.info("OOB marker cleanup thread stopped")
        
        if self.oob_server:
            try:
                self.oob_server.shutdown()
                PortAllocator.release_port(self.oob_port)
                logging.info(f"OOB HTTP server stopped (port {self.oob_port})")
            except Exception as e:
                logging.warning(f"Error stopping OOB HTTP server: {e}")
        if self.enable_advanced_oob:
            if self.smtp_oob_handler:
                try:
                    self.smtp_oob_handler.stop()
                    logging.info("SMTP OOB server stopped")
                except Exception as e:
                    logging.warning(f"Error stopping SMTP OOB server: {e}")
            if self.dns_oob_listener:
                try:
                    self.dns_oob_listener.stop()
                    logging.info("DNS OOB listener stopped")
                except Exception as e:
                    logging.warning(f"Error stopping DNS OOB listener: {e}")
            if self.icmp_oob_listener:
                try:
                    self.icmp_oob_listener.stop_listener()
                    logging.info("ICMP OOB listener stopped")
                except Exception as e:
                    logging.warning(f"Error stopping ICMP OOB listener: {e}")
            if self.https_oob_server:
                try:
                    self.https_oob_server.shutdown()
                    PortAllocator.release_port(self.https_oob_port)
                    logging.info(f"OOB HTTPS server stopped (port {self.https_oob_port})")
                except Exception as e:
                    logging.warning(f"Error stopping OOB HTTPS server: {e}")

# ---------------------------------------------------------------------
# REPORTING ENGINE
# ---------------------------------------------------------------------
class ReportingEngine:
    def __init__(self, config, signals, session_manager=None, cve_template_engine=None, fp_db=None):
        self.config = config
        self.signals = signals
        
        # Use disk-based vulnerability storage to prevent memory bloat during long scans
        vuln_storage_config = config.get('vulnerability_storage', {})
        db_path = vuln_storage_config.get('db_path', 'vulnerability_storage.db')
        self.vulnerability_storage = DiskBasedVulnerabilityStorage(db_path)
        
        # Keep in-memory list for backward compatibility and quick access
        self.vulnerabilities = []
        
        # Use shared FP_Database instance if provided, otherwise create new one
        self.fp_db = fp_db if fp_db is not None else FP_Database(config=config)
        self.session_manager = session_manager
        self.cve_template_engine = cve_template_engine
        # Lock for vulnerability deduplication to prevent race conditions
        self.vulnerability_lock = asyncio.Lock()
    def log(self, msg):
        if hasattr(self.signals, 'log'):
            self.signals.log.emit(msg)
        else:
            logging.info(msg)
    def add_finding(self, vuln):
        # Add to vulnerabilities list for export purposes (maintain backward compatibility)
        self.vulnerabilities.append(vuln)
        
        # Also store in disk-based database to prevent memory bloat during long scans
        try:
            self.vulnerability_storage.add_vulnerability(vuln)
        except Exception as e:
            logging.warning(f"Failed to store vulnerability in database: {e}")
        
        # Use CVE template engine if available to enhance vulnerability data
        if self.cve_template_engine:
            vuln = self._enhance_with_cve_templates(vuln)
        
        # Emit signal for GUI display
        if hasattr(self.signals, 'finding'):
            self.signals.finding.emit(vuln)
        else:
            logging.info(f"Finding: {vuln}")
    
    def _enhance_with_cve_templates(self, vuln):
        """
        Enhance vulnerability data with information from CVE templates.
        
        Args:
            vuln: Vulnerability dictionary
            
        Returns:
            dict: Enhanced vulnerability dictionary
        """
        if self.cve_template_engine:
            return self.cve_template_engine.apply_template_to_vulnerability(vuln)
        return vuln
    
    def update_progress(self, current, total):
        if hasattr(self.signals, 'progress'):
            self.signals.progress.emit(current, total)
        else:
            logging.info(f"Progress: {current}/{total}")
    
    def _generate_cvss_vector(self, vuln):
        """Generate dynamic CVSS 4.0 vector based on vulnerability context"""
        vuln_type = vuln.get('type', 'Unknown')
        
        # Base CVSS 4.0 metrics
        # Attack Vector (AV): Network (N), Adjacent (A), Local (L), Physical (P)
        av = 'N'  # Most web vulns are network-based
        
        # Attack Complexity (AC): Low (L), High (H)
        ac = 'L'  # Default to low complexity
        
        # Attack Requirements (AT): None (N)
        at = 'N'
        
        # Privileges Required (PR): None (N), Low (L), High (H)
        # Adjust based on vulnerability type and context
        if vuln_type in ['IDOR', 'SSRF', 'XXE']:
            pr = 'L'  # May require some privileges
        elif vuln_type in ['Privilege Escalation', 'Authentication Bypass']:
            pr = 'N'  # Exploits lack of privileges
        else:
            pr = 'N'  # Default to no privileges required
        
        # User Interaction (UI): None (N), Required (R)
        # Adjust based on vulnerability type
        if vuln_type == 'XSS':
            # Check if it's stored or reflected
            if vuln.get('subtype', '').lower() == 'stored':
                ui = 'N'  # Stored XSS doesn't require user interaction beyond viewing
            else:
                ui = 'R'  # Reflected XSS requires user interaction (clicking link)
        elif vuln_type in ['CSRF', 'OpenRedirect']:
            ui = 'R'  # Requires user interaction
        else:
            ui = 'N'  # Most injection vulns don't require user interaction
        
        # Vulnerable System Impact (VC, VI, VA): High (H), Low (L), None (N)
        # Subsequent System Impact (SC, SI, SA): High (H), Low (L), None (N)
        
        # Set impacts based on vulnerability type
        if vuln_type in ['SQLi', 'CommandInjection', 'RCE']:
            # High impact on confidentiality, integrity, availability
            vc, vi, va = 'H', 'H', 'H'
            sc, si, sa = 'H', 'H', 'H'  # Likely to affect subsequent systems
        elif vuln_type == 'XSS':
            # High impact on confidentiality and integrity, low on availability
            vc, vi, va = 'H', 'H', 'L'
            sc, si, sa = 'H', 'H', 'N'  # Can affect other systems via session hijacking
        elif vuln_type in ['SSRF', 'XXE']:
            # High impact on confidentiality, medium on integrity
            vc, vi, va = 'H', 'H', 'L'
            sc, si, sa = 'H', 'L', 'N'
        elif vuln_type in ['IDOR', 'Information Disclosure']:
            # High impact on confidentiality only
            vc, vi, va = 'H', 'N', 'N'
            sc, si, sa = 'H', 'N', 'N'
        elif vuln_type in ['CSRF']:
            # High impact on integrity, low on confidentiality
            vc, vi, va = 'L', 'H', 'L'
            sc, si, sa = 'N', 'H', 'N'
        else:
            # Default high impact
            vc, vi, va = 'H', 'H', 'H'
            sc, si, sa = 'N', 'N', 'N'
        
        # Construct CVSS 4.0 vector
        vector = f"CVSS:4.0/AV:{av}/AC:{ac}/AT:{at}/PR:{pr}/UI:{ui}/VC:{vc}/VI:{vi}/VA:{va}/SC:{sc}/SI:{si}/SA:{sa}"
        return vector
    
    def calculate_cvss(self, vuln):
        if not CVSS_AVAILABLE:
            return None
        try:
            vector = self._generate_cvss_vector(vuln)
            c = CVSS4(vector)
            return c.score
        except Exception as e:
            logging.warning(f"CVSS calculation error: {e}")
            return None
    def export_burp_xml(self, report):
        xml = '<?xml version="1.0"?>\n<issues>\n'
        for vuln in report['vulnerabilities']:
            xml += f"""<issue>
    <serialNumber>{vuln.get('id','')}</serialNumber>
    <type>{vuln['type']}</type>
    <name>{vuln['type']}</name>
    <host ip="unknown">{urlparse(vuln['url']).hostname}</host>
    <path>{urlparse(vuln['url']).path}</path>
    <location>{vuln['url']}</location>
    <severity>{vuln['severity']}</severity>
    <confidence>{vuln['confidence']}</confidence>
    <issueDetail>{vuln.get('evidence','')}</issueDetail>
</issue>\n"""
        xml += '</issues>'
        return xml
    async def send_jira_alert(self, vuln):
        jira_url = self.config.get('jira_webhook')
        if jira_url:
            try:
                if self.session_manager and self.session_manager.async_session:
                    async with self.session_manager.async_session.session.request('POST', jira_url, json={"title": f"UltraDAST found {vuln['type']}", "description": json.dumps(vuln)}) as resp:
                        if resp.status == 200:
                            self.log(f"JIRA alert sent for {vuln['type']}")
                else:
                    async with aiohttp.ClientSession() as session:
                        await session.post(jira_url, json={"title": f"UltraDAST found {vuln['type']}", "description": json.dumps(vuln)})
                        self.log(f"JIRA alert sent for {vuln['type']}")
            except Exception as e:
                self.log(f"Failed to send JIRA alert: {e}")
    async def send_slack_alert(self, vuln):
        slack_url = self.config.get('slack_webhook')
        if slack_url:
            try:
                if self.session_manager and self.session_manager.async_session:
                    async with self.session_manager.async_session.session.request('POST', slack_url, json={"text": f"*{vuln['type']}* on {vuln['url']}\nEvidence: {vuln.get('evidence','')}"}) as resp:
                        if resp.status == 200:
                            self.log(f"Slack alert sent for {vuln['type']}")
                else:
                    async with aiohttp.ClientSession() as session:
                        await session.post(slack_url, json={"text": f"*{vuln['type']}* on {vuln['url']}\nEvidence: {vuln.get('evidence','')}"})
                        self.log(f"Slack alert sent for {vuln['type']}")
            except Exception as e:
                self.log(f"Failed to send Slack alert: {e}")
    async def close(self):
        if self.fp_db:
            try:
                await self.fp_db.close()
            except Exception as e:
                logging.warning(f"Error closing FP database: {e}")
        
        # Close vulnerability storage to prevent resource leaks
        if hasattr(self, 'vulnerability_storage'):
            try:
                self.vulnerability_storage.close()
                logging.info("ReportingEngine: Vulnerability storage closed")
            except Exception as e:
                logging.warning(f"Error closing vulnerability storage: {e}")
    
    def format_taint_vulnerability(self, taint_vuln: Dict) -> Dict:
        """Format taint tracking vulnerability for standard reporting"""
        formatted = {
            'id': str(uuid.uuid4()),
            'type': taint_vuln.get('type', 'DataFlow'),
            'url': taint_vuln.get('url', ''),
            'severity': taint_vuln.get('severity', 'MEDIUM'),
            'confidence': taint_vuln.get('confidence', 'HIGH'),
            'evidence': taint_vuln.get('evidence', ''),
            'parameter': taint_vuln.get('targeted_parameter', taint_vuln.get('parameter', '')),
            'payload': taint_vuln.get('payload', ''),
            'detection_method': taint_vuln.get('detection_method', 'dynamic_taint_tracking'),
            'discovery_phase': taint_vuln.get('discovery_phase', 'unknown'),
            'cwe': self._get_cwe_for_taint_type(taint_vuln.get('type', '')),
            'cvss_score': taint_vuln.get('cvss_score', 5.0),
            'taint_id': taint_vuln.get('taint_id', ''),
            'sink_pattern': taint_vuln.get('sink_pattern', ''),
            'response_headers': taint_vuln.get('response_headers', {}),
            'timestamp': datetime.now().isoformat()
        }
        
        # Add symbolic execution data if available
        if 'symbolic_execution' in taint_vuln:
            formatted['symbolic_execution'] = taint_vuln['symbolic_execution']
        
        return formatted
    
    def _get_cwe_for_taint_type(self, taint_type: str) -> str:
        """Map taint types to CWE identifiers"""
        cwe_mapping = {
            'SQLi': 'CWE-89',
            'CommandInjection': 'CWE-78',
            'XSS': 'CWE-79',
            'PathTraversal': 'CWE-22',
            'DataFlow': 'CWE-200'
        }
        return cwe_mapping.get(taint_type, 'CWE-200')
    
    def generate_taint_summary(self, taint_results: List[Dict]) -> Dict:
        """Generate summary statistics for taint tracking results"""
        summary = {
            'total_taint_flows': len(taint_results),
            'by_severity': {'Critical': 0, 'High': 0, 'Medium': 0, 'Low': 0},
            'by_type': {},
            'by_detection_method': {},
            'symbolic_execution_stats': {
                'paths_explored': 0,
                'symbolic_variables_found': 0
            }
        }
        
        for result in taint_results:
            # Count by severity
            severity = result.get('severity', 'Medium')
            if severity in summary['by_severity']:
                summary['by_severity'][severity] += 1
            
            # Count by type
            vuln_type = result.get('type', 'Unknown')
            summary['by_type'][vuln_type] = summary['by_type'].get(vuln_type, 0) + 1
            
            # Count by detection method
            detection_method = result.get('detection_method', 'unknown')
            summary['by_detection_method'][detection_method] = summary['by_detection_method'].get(detection_method, 0) + 1
            
            # Collect symbolic execution stats
            if 'symbolic_execution' in result:
                sym_exec = result['symbolic_execution']
                summary['symbolic_execution_stats']['paths_explored'] += sym_exec.get('paths_explored', 0)
                summary['symbolic_execution_stats']['symbolic_variables_found'] += len(sym_exec.get('symbolic_variables', {}))
        
        return summary

# ---------------------------------------------------------------------
# HEURISTIC REGRESSION ORACLE
# ---------------------------------------------------------------------
class HeuristicRegressionOracle:
    """
    Heuristic Regression Oracle for eliminating false positives in fuzzing.
    
    This class implements a three-step approach to reduce noise:
    Step A: Build a noise profile from benign requests (baseline response time + standard deviation + typical status codes)
    Step B: Enter regression mode when 500 errors are detected during fuzzing
    Step C: Verify consistency by sending the same payload 3 times with delays
    
    Only confirmed, reproducible anomalies are saved to the database.
    """
    
    def __init__(self, config, session_manager, db_path='anomalies.db'):
        self.config = config
        self.session_manager = session_manager
        self.db_path = db_path
        self.enabled = config.get('heuristic_regression_oracle', {}).get('enabled', True)
        self.benign_sample_size = config.get('heuristic_regression_oracle', {}).get('benign_sample_size', 50)
        self.regression_retries = config.get('heuristic_regression_oracle', {}).get('regression_retries', 3)
        self.regression_delay = config.get('heuristic_regression_oracle', {}).get('regression_delay', 1.0)
        self.noise_profiles = {}  # Store noise profiles per endpoint
        self.regression_mode = False
        self.current_payload = None
        self.filtered_errors = 0  # Track number of transient errors filtered out
        self._db_initialized = False
        
    async def async_init(self):
        """Async initialization method to avoid blocking the event loop."""
        if not self._db_initialized:
            await self._init_database()
            self._db_initialized = True
        
    async def _init_database(self):
        """Initialize SQLite database for storing confirmed anomalies asynchronously."""
        def _init_db_sync():
            try:
                conn = sqlite3.connect(self.db_path)
                cursor = conn.cursor()
                cursor.execute('''
                    CREATE TABLE IF NOT EXISTS anomalies (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        endpoint TEXT NOT NULL,
                        payload TEXT NOT NULL,
                        method TEXT NOT NULL,
                        status_code INTEGER NOT NULL,
                        response_time REAL NOT NULL,
                        response_body TEXT,
                        response_headers TEXT,
                        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                        confirmation_count INTEGER DEFAULT 1,
                        noise_profile_baseline REAL,
                        noise_profile_stddev REAL,
                        UNIQUE(endpoint, payload, method)
                    )
                ''')
                cursor.execute('''
                    CREATE INDEX IF NOT EXISTS idx_endpoint ON anomalies(endpoint)
                ''')
                cursor.execute('''
                    CREATE INDEX IF NOT EXISTS idx_timestamp ON anomalies(timestamp)
                ''')
                cursor.execute('''
                    CREATE INDEX IF NOT EXISTS idx_cleanup ON anomalies(timestamp)
                ''')
                conn.commit()
                conn.close()
                logging.info(f"HeuristicRegressionOracle: Database initialized at {self.db_path}")
            except Exception as e:
                logging.error(f"HeuristicRegressionOracle: Failed to initialize database: {e}")
        
        loop = asyncio.get_event_loop()
        await loop.run_in_executor(None, _init_db_sync)
    
    async def build_noise_profile(self, url, method='GET', headers=None, data=None, json_data=None):
        """
        Step A: Build a noise profile from benign requests.
        
        Sends benign requests to establish baseline metrics:
        - Average response time
        - Standard deviation of response times
        - Typical status codes
        
        Args:
            url: Target endpoint URL
            method: HTTP method
            headers: Request headers
            data: Form data
            json_data: JSON data
            
        Returns:
            Dictionary with noise profile metrics
        """
        if not self.enabled:
            return None
            
        endpoint_key = f"{method}:{url}"
        logging.info(f"HeuristicRegressionOracle: Building noise profile for {endpoint_key}")
        
        response_times = []
        status_codes = []
        
        for i in range(self.benign_sample_size):
            try:
                start_time = time.time()
                resp = await self.session_manager.fetch(
                    url, method=method, data=data, json_data=json_data,
                    headers=headers, allow_redirects=True, use_cache=False
                )
                elapsed = time.time() - start_time
                
                if resp:
                    response_times.append(elapsed)
                    status_codes.append(resp.status)
                    
                # Small delay between samples to avoid overwhelming the server
                await asyncio.sleep(0.1)
                
            except Exception as e:
                logging.debug(f"Noise profile sample {i+1} failed: {e}")
                continue
        
        if response_times:
            avg_time = statistics.mean(response_times)
            stddev_time = statistics.stdev(response_times) if len(response_times) > 1 else 0
            common_status = max(set(status_codes), key=status_codes.count) if status_codes else None
            
            noise_profile = {
                'avg_response_time': avg_time,
                'stddev_response_time': stddev_time,
                'common_status_code': common_status,
                'sample_count': len(response_times),
                'endpoint': url,
                'method': method
            }
            
            self.noise_profiles[endpoint_key] = noise_profile
            logging.info(f"HeuristicRegressionOracle: Noise profile for {endpoint_key} - "
                        f"Avg: {avg_time:.3f}s, StdDev: {stddev_time:.3f}s, "
                        f"Common Status: {common_status}, Samples: {len(response_times)}")
            
            return noise_profile
        else:
            logging.warning(f"HeuristicRegressionOracle: Failed to build noise profile for {endpoint_key}")
            return None
    
    def get_noise_profile(self, url, method='GET'):
        """Get existing noise profile for an endpoint."""
        endpoint_key = f"{method}:{url}"
        return self.noise_profiles.get(endpoint_key)
    
    async def enter_regression_mode(self, url, method, payload, headers=None, data=None, json_data=None):
        """
        Step C: Regression Mode - Verify consistency of 500 errors.
        
        When a 500 error is detected, send the exact same payload multiple times
        with delays to verify it's not a transient network issue.
        
        Args:
            url: Target endpoint URL
            method: HTTP method
            payload: The payload that triggered the 500 error
            headers: Request headers
            data: Form data
            json_data: JSON data
            
        Returns:
            Dictionary with regression test results
        """
        if not self.enabled:
            return {'is_confirmed': False, 'reason': 'HeuristicRegressionOracle disabled'}
        
        endpoint_key = f"{method}:{url}"
        noise_profile = self.get_noise_profile(url, method)
        
        logging.info(f"HeuristicRegressionOracle: Entering regression mode for {endpoint_key}")
        self.regression_mode = True
        self.current_payload = payload
        
        regression_results = []
        confirmed_errors = 0
        
        for attempt in range(self.regression_retries):
            try:
                start_time = time.time()
                resp = await self.session_manager.fetch(
                    url, method=method, data=data, json_data=json_data,
                    headers=headers, allow_redirects=True, use_cache=False
                )
                elapsed = time.time() - start_time
                
                if resp and resp.status >= 500:
                    confirmed_errors += 1
                    regression_results.append({
                        'attempt': attempt + 1,
                        'status': resp.status,
                        'response_time': elapsed,
                        'is_error': True
                    })
                    logging.warning(f"Regression attempt {attempt + 1}: 500 error confirmed "
                                  f"(status={resp.status}, time={elapsed:.3f}s)")
                else:
                    regression_results.append({
                        'attempt': attempt + 1,
                        'status': resp.status if resp else 'error',
                        'response_time': elapsed,
                        'is_error': False
                    })
                    logging.info(f"Regression attempt {attempt + 1}: Error disappeared "
                               f"(status={resp.status if resp else 'error'}, time={elapsed:.3f}s)")
                
                # Delay between regression attempts
                if attempt < self.regression_retries - 1:
                    await asyncio.sleep(self.regression_delay)
                    
            except Exception as e:
                regression_results.append({
                    'attempt': attempt + 1,
                    'status': 'exception',
                    'response_time': 0,
                    'is_error': False,
                    'error': str(e)
                })
                logging.debug(f"Regression attempt {attempt + 1} failed with exception: {e}")
        
        self.regression_mode = False
        self.current_payload = None
        
        # Determine if the error is consistent
        is_confirmed = confirmed_errors >= self.regression_retries * 0.5  # At least 50% consistency
        
        result = {
            'is_confirmed': is_confirmed,
            'confirmed_errors': confirmed_errors,
            'total_attempts': self.regression_retries,
            'regression_results': regression_results,
            'noise_profile': noise_profile
        }
        
        if is_confirmed:
            result['reason'] = f'Error confirmed in {confirmed_errors}/{self.regression_retries} attempts'
            logging.warning(f"HeuristicRegressionOracle: Confirmed anomaly for {endpoint_key} - "
                          f"{confirmed_errors}/{self.regression_retries} attempts failed")
        else:
            result['reason'] = f'Error was transient - only {confirmed_errors}/{self.regression_retries} attempts failed'
            logging.info(f"HeuristicRegressionOracle: Transient error for {endpoint_key} - "
                        f"only {confirmed_errors}/{self.regression_retries} attempts failed")
            self.filtered_errors += 1  # Track filtered transient errors
        
        return result
    
    async def save_confirmed_anomaly(self, url, method, payload, status_code, response_time, 
                                    response_body=None, response_headers=None):
        """
        Save a confirmed anomaly to the database asynchronously.
        
        Args:
            url: Target endpoint URL
            method: HTTP method
            payload: The payload that triggered the anomaly
            status_code: HTTP status code
            response_time: Response time
            response_body: Response body
            response_headers: Response headers
        """
        if not self.enabled:
            return
        
        endpoint_key = f"{method}:{url}"
        noise_profile = self.get_noise_profile(url, method)
        
        def _save_anomaly_sync():
            try:
                conn = sqlite3.connect(self.db_path)
                cursor = conn.cursor()
                
                # Check if this anomaly already exists
                cursor.execute('''
                    SELECT id, confirmation_count FROM anomalies 
                    WHERE endpoint = ? AND payload = ? AND method = ?
                ''', (url, payload, method))
                
                existing = cursor.fetchone()
                
                if existing:
                    # Update confirmation count
                    anomaly_id, confirmation_count = existing
                    cursor.execute('''
                        UPDATE anomalies 
                        SET confirmation_count = confirmation_count + 1,
                            timestamp = CURRENT_TIMESTAMP
                        WHERE id = ?
                    ''', (anomaly_id,))
                    logging.info(f"HeuristicRegressionOracle: Updated existing anomaly {anomaly_id} "
                               f"(confirmation count: {confirmation_count + 1})")
                else:
                    # Insert new anomaly
                    cursor.execute('''
                        INSERT INTO anomalies (
                            endpoint, payload, method, status_code, response_time,
                            response_body, response_headers, noise_profile_baseline, noise_profile_stddev
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ''', (
                        url, payload, method, status_code, response_time,
                        response_body[:10000] if response_body else None,  # Limit body size
                        str(response_headers)[:5000] if response_headers else None,  # Limit headers size
                        noise_profile.get('avg_response_time') if noise_profile else None,
                        noise_profile.get('stddev_response_time') if noise_profile else None
                    ))
                    logging.warning(f"HeuristicRegressionOracle: Saved new confirmed anomaly for {endpoint_key}")
                
                conn.commit()
                conn.close()
                
            except Exception as e:
                logging.error(f"HeuristicRegressionOracle: Failed to save anomaly: {e}")
        
        loop = asyncio.get_event_loop()
        await loop.run_in_executor(None, _save_anomaly_sync)
    
    async def get_anomaly_count(self):
        """Get total count of confirmed anomalies in database asynchronously."""
        def _get_count_sync():
            try:
                conn = sqlite3.connect(self.db_path)
                cursor = conn.cursor()
                cursor.execute('SELECT COUNT(*) FROM anomalies')
                count = cursor.fetchone()[0]
                conn.close()
                return count
            except Exception as e:
                logging.error(f"HeuristicRegressionOracle: Failed to get anomaly count: {e}")
                return 0
        
        loop = asyncio.get_event_loop()
        return await loop.run_in_executor(None, _get_count_sync)
    
    async def get_recent_anomalies(self, limit=10):
        """Get recent confirmed anomalies from database asynchronously."""
        def _get_recent_sync():
            try:
                conn = sqlite3.connect(self.db_path)
                cursor = conn.cursor()
                cursor.execute('''
                    SELECT endpoint, method, status_code, response_time, 
                           timestamp, confirmation_count, payload
                    FROM anomalies 
                    ORDER BY timestamp DESC 
                    LIMIT ?
                ''', (limit,))
                
                anomalies = []
                for row in cursor.fetchall():
                    anomalies.append({
                        'endpoint': row[0],
                        'method': row[1],
                        'status_code': row[2],
                        'response_time': row[3],
                        'timestamp': row[4],
                        'confirmation_count': row[5],
                        'payload': row[6][:100] + '...' if len(row[6]) > 100 else row[6]
                    })
                
                conn.close()
                return anomalies
            except Exception as e:
                logging.error(f"HeuristicRegressionOracle: Failed to get recent anomalies: {e}")
                return []
        
        loop = asyncio.get_event_loop()
        return await loop.run_in_executor(None, _get_recent_sync)

    async def cleanup_old_anomalies(self, max_age_days=30, max_records=10000):
        """
        Clean up old anomalies to prevent unbounded database growth.
        
        Args:
            max_age_days: Maximum age of records to keep (default: 30 days)
            max_records: Maximum total records to keep (default: 10000)
        """
        def _cleanup_sync():
            try:
                conn = sqlite3.connect(self.db_path)
                cursor = conn.cursor()
                
                # Delete records older than max_age_days
                cutoff_date = datetime.now() - timedelta(days=max_age_days)
                cursor.execute('''
                    DELETE FROM anomalies 
                    WHERE timestamp < datetime(?)
                ''', (cutoff_date.isoformat(),))
                
                deleted_old = cursor.rowcount
                
                # If still too many records, delete oldest ones
                cursor.execute('SELECT COUNT(*) FROM anomalies')
                total_count = cursor.fetchone()[0]
                
                if total_count > max_records:
                    excess = total_count - max_records
                    cursor.execute('''
                        DELETE FROM anomalies 
                        WHERE id IN (
                            SELECT id FROM anomalies 
                            ORDER BY timestamp ASC 
                            LIMIT ?
                        )
                    ''', (excess,))
                    deleted_excess = cursor.rowcount
                else:
                    deleted_excess = 0
                
                conn.commit()
                conn.close()
                
                total_deleted = deleted_old + deleted_excess
                if total_deleted > 0:
                    logging.info(f"HeuristicRegressionOracle: Cleaned up {total_deleted} old anomalies "
                               f"({deleted_old} by age, {deleted_excess} by count limit)")
                
                return total_deleted
            except Exception as e:
                logging.error(f"HeuristicRegressionOracle: Failed to cleanup old anomalies: {e}")
                return 0
        
        loop = asyncio.get_event_loop()
        return await loop.run_in_executor(None, _cleanup_sync)

    async def close(self):
        """Close database connection to prevent resource leaks."""
        # HeuristicRegressionOracle uses short-lived connections that are closed immediately
        # This method is provided for consistency with other cleanup patterns
        try:
            # Clean up old anomalies before closing
            await self.cleanup_old_anomalies()
            
            # Log statistics before closing
            anomaly_count = await self.get_anomaly_count()
            recent_anomalies = await self.get_recent_anomalies(limit=5)
            logging.info(f"HeuristicRegressionOracle: Total confirmed anomalies: {anomaly_count}")
            if recent_anomalies:
                logging.info(f"HeuristicRegressionOracle: Recent anomalies: {recent_anomalies}")
        except Exception as e:
            logging.warning(f"HeuristicRegressionOracle: Error during cleanup: {e}")

