    async def _safe_request(self, method, url, **kwargs):
        """Make HTTP request using session manager with deduplication and HTTP/2/3 support"""
        try:
            # Check request deduplication if available
            if hasattr(self.scanner, 'request_deduplicator') and self.scanner.request_deduplicator:
                headers = kwargs.get('headers', {})
                data = kwargs.get('data', kwargs.get('json', None))
                if self.scanner.request_deduplicator.is_duplicate_request(method, url, headers, data):
                    logging.debug(f"Duplicate request skipped: {method} {url}")
                    return None
            
            # Try HTTP/2 if enabled and available
            if hasattr(self.scanner, 'http2_client') and self.scanner.http2_client and self.scanner.http2_client.enabled:
                try:
                    headers = kwargs.get('headers', {})
                    data = kwargs.get('data', kwargs.get('json', None))
                    http2_response = await self.scanner.http2_client.make_request(method, url, headers, data)
                    if http2_response:
                        logging.debug(f"HTTP/2 request successful: {method} {url}")
                        return http2_response
                except Exception as e:
                    logging.debug(f"HTTP/2 request failed, falling back: {e}")
            
            # Try HTTP/3 if enabled and available
            if hasattr(self.scanner, 'http3_client') and self.scanner.http3_client and self.scanner.http3_client.is_available():
                try:
                    headers = kwargs.get('headers', {})
                    data = kwargs.get('data', kwargs.get('json', None))
                    http3_response = await self.scanner.http3_client.make_request(method, url, headers, data)
                    if http3_response:
                        logging.debug(f"HTTP/3 request successful: {method} {url}")
                        return http3_response
                except Exception as e:
                    logging.debug(f"HTTP/3 request failed, falling back: {e}")
            
            return await self.session_manager.fetch(method, url, **kwargs)
        except Exception as e:
            logging.error(f"Request failed for {url}: {e}")
            return None
    async def _add_vulnerability(self, vuln):
        await self.scanner._add_vulnerability(vuln)
    
    def _build_raw_request_for_storage(self, method, url, headers, payload):
        """Helper method to build raw HTTP request for storage/export"""
        parsed_url = urlparse(url)
        path = parsed_url.path or '/'
        if parsed_url.query:
            path += '?' + parsed_url.query
        
        raw_request = f"{method} {path} HTTP/1.1\r\n"
        
        # Use custom Host header if provided, otherwise use parsed URL hostname (without port)
        # This preserves virtual host scanning capabilities
        host_header = headers.get('Host', parsed_url.hostname)
        raw_request += f"Host: {host_header}\r\n"
        
        # Add remaining headers, excluding Host since we already added it
        for header_name, header_value in headers.items():
            if header_name.lower() != 'host':
                raw_request += f"{header_name}: {header_value}\r\n"
        
        if payload:
            if isinstance(payload, dict):
                body_str = json.dumps(payload)
            else:
                body_str = str(payload)
            raw_request += f"Content-Length: {len(body_str)}\r\n"
            raw_request += "\r\n"
            raw_request += body_str
        else:
            raw_request += "\r\n"
        
        return raw_request
    async def _async_fetch(self, url, method='GET', data=None, json_data=None, headers=None, use_cache=True, session_manager: SessionStateManager = None, session_id: str = None, cookies=None):
        """
        Async fetch with global request cache support and CSRF token handling.
        
        Args:
            url: Target URL
            method: HTTP method
            data: POST data
            json_data: JSON data
            headers: HTTP headers
            use_cache: Whether to use request cache (default: True)
            session_manager: Optional SessionStateManager for CSRF token handling
            session_id: Optional session ID for CSRF token storage
            cookies: Optional cookies dict
        """
        # Apply maturity model safety checks
        if hasattr(self, 'maturity_model'):
            # Check if request should be sent based on dry-run mode
            if not self.maturity_model.should_send_request(url, method, data, headers):
                return None
            
            # Check payload safety based on maturity level
            payload_to_check = str(data) if data else str(json_data) if json_data else ''
            if payload_to_check:
                allowed, reason = self.maturity_model.is_payload_allowed(payload_to_check, method, url)
                if not allowed:
                    logging.info(f"[SAFETY] Payload blocked: {reason}")
                    return None
        
        if not self.session_manager or not self.session_manager.async_session:
            return None
        try:
            # Use session manager's fetch method which includes caching and CSRF handling
            resp = await self.session_manager.fetch(
                url, method=method, data=data, json_data=json_data, 
                headers=headers, allow_redirects=True, use_cache=use_cache,
                session_manager=session_manager, session_id=session_id, cookies=cookies
            )
            if resp:
                body = await resp.text()
                resp._body = body
                resp._elapsed = getattr(resp, '_elapsed', 0)
                return resp
            return None
        except (ConnectionError, asyncio.TimeoutError, aiohttp.ClientError) as e:
            logging.debug(f"Network error during async fetch for {url}: {e}")
            return None
        except Exception as e:
            logging.debug(f"Unexpected error during async fetch for {url}: {e}", exc_info=True)
            return None
