    async def close(self):
        """Clean up resources to prevent resource leaks."""
        # Cancel all background tasks
        if hasattr(self, 'background_task_manager'):
            await self.background_task_manager.cancel_all()
        
        # Cleanup JSRenderDriver manager
        if hasattr(self, 'js_driver_manager'):
            await self.js_driver_manager.cleanup()
        
        # Set stop event to ensure ongoing operations stop
        if hasattr(self, 'stop_event'):
            self.stop_event.set()
        
        logging.info("InjectionEngine: Resources cleaned up")
    async def second_order_injection_tests(self):
        self.log("Second-order injection tests...")
        stored_xss_payload = f"<img src=http://{self.public_ip}:{self.oob_port}/DAST_STORED_XSS_{self.oob_marker_base}>"
        stored_sqli_payload = f"' UNION SELECT 'DAST_STORED_SQL_{self.oob_marker_base}'--"
        
        # Track injection points for later verification with full context
        self.injection_points = []
        # Clean up expired injection points before adding new ones
        self._cleanup_expired_injection_points()
        
        for page in self.crawler_engine._get_crawled_pages_iterator():
            if not page.get('html'):
                # Load HTML from disk if not already loaded
                html = self.crawler_engine._get_html_content(page['url'])
                page['html'] = html if html else ''
            html = page.get('html', '')
            soup = get_cached_soup(html, 'html.parser')
            for form in soup.find_all('form', method=lambda m: m and m.lower() == 'post'):
                action = urljoin(page['url'], form.get('action',''))
                fields = [inp.get('name') for inp in form.find_all(['input','textarea','select']) if inp.get('name')]
                if any(kw in str(fields).lower() for kw in ['comment','bio','message','name','title','profile']):
                    data = {}
                    for name in fields:
                        if name.lower() in ('comment','message','bio','description'):
                            data[name] = stored_xss_payload
                        elif name.lower() in ('name','title','subject'):
                            data[name] = stored_sqli_payload
                        else:
                            data[name] = 'test'
                    
                    # Capture full context for later verification
                    try:
                        resp = await self._async_fetch(action, method='POST', data=data)
                        if resp:
                            injection_point = {
                                'url': action,
                                'referrer': page['url'],
                                'cookies': dict(resp.cookies) if resp.cookies else {},
                                'headers': dict(resp.headers) if resp.headers else {},
                                'data': data,
                                'timestamp': time.time()
                            }
                            self.injection_points.append(injection_point)
                            # Add to persistent queue for background retry processing
                            self.second_order_queue.add_injection_point(injection_point, self.injection_points_ttl)
                            self.log(f"Stored payload submitted to {action} with full context")
                    except Exception as e:
                        logging.warning(f"Error storing payload with context at {action}: {e}")
        
        if not self.injection_points:
            self.log("No suitable injection points found for second-order testing")
            return
        
        self.log(f"Submitted payloads to {len(self.injection_points)} injection points")
        
        # Start background retry processing for delayed verification
        self.background_task_manager.add_task(
            self._background_second_order_verification(stored_sqli_payload),
            "second_order_background_verification"
        )
        
        # Enhanced delayed verification with multiple intervals
        verification_intervals = [5, 15.0, 30, 60, 120]  # Progressive delays
        max_total_timeout = 300  # 5 minutes total
        
        # Discover high-priority targets (admin, dashboard, profile pages)
        high_priority_urls = self._discover_high_priority_targets()
        self.log(f"Found {len(high_priority_urls)} high-priority targets for delayed verification")
        
        start_time = time.time()
        last_verification = 0
        
        while time.time() - start_time < max_total_timeout:
            current_time = time.time()
            elapsed = current_time - start_time
            
            # Determine if we should verify at this interval
            should_verify = False
            for interval in verification_intervals:
                if elapsed >= interval and last_verification < interval:
                    should_verify = True
                    last_verification = interval
                    break
            
            if should_verify:
                self.log(f"Performing delayed verification at {elapsed:.0f}s...")
                
                # Check high-priority URLs first
                await self._verify_second_order_injection(high_priority_urls, stored_sqli_payload)
                
                # Then check all crawled URLs
                await self._verify_second_order_injection(list(self.crawler_engine.visited_urls), stored_sqli_payload)
                
                # Re-crawl to discover new pages that might contain injected content
                if elapsed >= 30:  # Re-crawl after 30 seconds
                    self.log("Re-crawling to discover potential delayed trigger pages...")
                    await self._delayed_recrawl()
            
            # Check for OOB callbacks (more frequent) with persistent waiting
            # Check for stored XSS markers using persistent callback detection
            stored_xss_callback = await wait_for_oob_callback_async("DAST_STORED_XSS", timeout_seconds=30, check_interval=0.5)
            if stored_xss_callback:
                confidence = calculate_evidence_based_confidence(
                    evidence_strength='critical',
                    baseline_excluded=True,
                    multiple_confirmations=True,
                    specificity='high',
                    false_positive_resistance='high'
                )
                await self._add_vulnerability({
                    "type":"Second-order XSS","url":stored_xss_callback['path'],"parameter":"*",
                    "evidence":f"OOB callback from stored XSS (injected at {len(self.injection_points)} points)",
                    "severity":"High","confidence":confidence,"cwe":CWE_MAP["XSS"]
                })
                self.log(f"Second-order XSS confirmed via OOB callback after {elapsed:.0f}s")
                return
            
            # Adaptive sleep based on elapsed time
            if elapsed < 30:
                await asyncio.sleep(2)  # Check frequently early
            elif elapsed < 120:
                await asyncio.sleep(5)  # Moderate frequency
            else:
                await asyncio.sleep(10)  # Less frequent later
        
        self.log(f"Second-order injection testing completed after {max_total_timeout}s with no OOB callbacks")
    
    async def _background_second_order_verification(self, sqli_payload):
        """Background task for persistent retry of delayed second-order injection verification."""
        self.log("Starting background second-order injection verification...")
        
        while not self.stop_event.is_set():
            try:
                # Clean up expired injection points
                self.second_order_queue.cleanup_expired_injection_points()
                
                # Get pending injection points for retry
                pending_points = self.second_order_queue.get_pending_injection_points(limit=50)
                
                if pending_points:
                    self.log(f"Retrying verification for {len(pending_points)} pending injection points")
                    
                    # Discover high-priority targets
                    high_priority_urls = self._discover_high_priority_targets()
                    all_urls = list(self.crawler_engine.visited_urls) if self.crawler_engine else []
                    
                    for injection_point in pending_points:
                        try:
                            # Verify with context replay
                            url = injection_point['url']
                            
                            # Try context-aware verification first
                            if injection_point['cookies'] and injection_point['headers']:
                                headers = {
                                    'Referer': injection_point['referrer']
                                }
                                headers.update(injection_point['headers'])
                                
                                resp = await self._async_fetch(url, headers=headers, cookies=injection_point['cookies'])
                                if resp:
                                    html = resp._body
                                    validation_result = validate_sqli_error_message(html)
                                    if validation_result['is_valid_sqli']:
                                        confidence = calculate_evidence_based_confidence(
                                            evidence_strength='critical',
                                            baseline_excluded=True,
                                            multiple_confirmations=True,
                                            specificity='high',
                                            false_positive_resistance='high'
                                        )
                                        await self._add_vulnerability({
                                            "type":"Second-order SQLi","url":url,"parameter":"*",
                                            "evidence":f"Marker found with background retry: {sqli_payload}",
                                            "severity":"Critical","confidence":confidence,"cwe":CWE_MAP["SQLi"]
                                        })
                                        self.log(f"Second-order SQLi confirmed at {url} via background retry")
                                        self.second_order_queue.update_retry_count(injection_point['id'], success=True)
                                        continue
                            
                            # Try normal verification if context-aware failed
                            resp = await self._async_fetch(url)
                            if resp:
                                html = resp._body
                                validation_result = validate_sqli_error_message(html)
                                if validation_result['is_valid_sqli']:
                                    confidence = calculate_evidence_based_confidence(
                                        evidence_strength='moderate',
                                        baseline_excluded=True,
                                        multiple_confirmations=False,
                                        specificity='medium',
                                        false_positive_resistance='medium'
                                    )
                                    await self._add_vulnerability({
                                        "type":"Second-order SQLi","url":url,"parameter":"*",
                                        "evidence":f"Marker found via background retry: {sqli_payload}",
                                        "severity":"High","confidence":confidence,"cwe":CWE_MAP["SQLi"]
                                    })
                                    self.log(f"Second-order SQLi confirmed at {url} via background retry (no context)")
                                    self.second_order_queue.update_retry_count(injection_point['id'], success=True)
                                    continue
                            
                            # Update retry count if verification failed
                            self.second_order_queue.update_retry_count(injection_point['id'], success=False)
                            
                        except Exception as e:
                            logging.debug(f"Background verification error for {injection_point['url']}: {e}")
                            self.second_order_queue.update_retry_count(injection_point['id'], success=False)
                
                # Get queue statistics
                queue_stats = self.second_order_queue.get_queue_stats()
                self.log(f"Background verification queue stats: {queue_stats}")
                
                # Wait before next retry cycle (exponential backoff)
                await asyncio.sleep(60)  # Check every minute
                
            except Exception as e:
                logging.error(f"Error in background second-order verification: {e}")
                await asyncio.sleep(120)  # Wait longer on error
    
    def _discover_high_priority_targets(self):
        """Discover high-priority URLs likely to trigger second-order vulnerabilities."""
        high_priority = set()
        admin_keywords = ['admin', 'dashboard', 'panel', 'manage', 'moderator', 'review']
        user_keywords = ['profile', 'account', 'settings', 'user', 'my']
        
        for url in self.crawler_engine.visited_urls:
            url_lower = url.lower()
            if any(kw in url_lower for kw in admin_keywords + user_keywords):
                high_priority.add(url)
        
        # Also check for common admin paths
        base_urls = set()
        for url in self.crawler_engine.visited_urls:
            parsed = urlparse(url)
            base = f"{parsed.scheme}://{parsed.netloc}"
            base_urls.add(base)
        
        for base in base_urls:
            for path in ['/admin', '/dashboard', '/admin/', '/dashboard/', '/panel', '/manage']:
                high_priority.add(f"{base}{path}")
        
        return list(high_priority)
    
    def _cleanup_expired_injection_points(self):
        """Remove expired injection points based on TTL to prevent false negatives from stale context."""
        current_time = time.time()
        ttl = getattr(self, 'injection_points_ttl', 300)  # Default 5 minutes
        
        # Filter out expired injection points
        original_count = len(self.injection_points)
        self.injection_points = [
            point for point in self.injection_points 
            if current_time - point.get('timestamp', 0) < ttl
        ]
        
        removed_count = original_count - len(self.injection_points)
        if removed_count > 0:
            logging.info(f"Cleaned up {removed_count} expired injection points (TTL: {ttl}s)")
    
    async def _verify_second_order_injection(self, urls, sqli_payload):
        """Verify if second-order SQLi payload appears in given URLs with full context replay."""
        # Clean up expired injection points before verification
        self._cleanup_expired_injection_points()
        
        # Check if context verification is enabled
        context_verification_enabled = self.config.get('context_verification_enabled', True)
        
        for url in urls:
            try:
                # Try to verify with original injection context first
                verified_with_context = False
                
                if context_verification_enabled:
                    # Try each injection point's context
                    for injection_point in self.injection_points:
                        # Check if injection point has expired
                        injection_age = time.time() - injection_point.get('timestamp', 0)
                        ttl = getattr(self, 'injection_points_ttl', 300)
                        
                        if injection_age >= ttl:
                            logging.debug(f"Skipping expired injection point at {injection_point['url']} (age: {injection_age:.0f}s, TTL: {ttl}s)")
                            continue
                            
                        if url == injection_point['url']:
                            # Replay the exact referrer and cookie chain
                            headers = {
                                'Referer': injection_point['referrer']
                            }
                        
                        # Merge with original headers from injection
                        if injection_point['headers']:
                            headers.update(injection_point['headers'])
                        
                        # Only use cookies if they're still valid (not expired)
                        if injection_age < ttl and injection_point['cookies']:
                            resp = await self._async_fetch(url, headers=headers, cookies=injection_point['cookies'])
                        else:
                            resp = await self._async_fetch(url, headers=headers)
                        if resp:
                            html = resp._body
                            # Use enhanced SQL dialect validation
                            validation_result = validate_sqli_error_message(html)
                            if validation_result['is_valid_sqli']:
                                confidence = calculate_evidence_based_confidence(
                                    evidence_strength='critical',
                                    baseline_excluded=True,
                                    multiple_confirmations=True,
                                    specificity='high',
                                    false_positive_resistance='high'
                                )
                                await self._add_vulnerability({
                                    "type":"Second-order SQLi","url":url,"parameter":"*",
                                    "evidence":f"Marker found with context replay: {sqli_payload}",
                                    "severity":"Critical","confidence":confidence,"cwe":CWE_MAP["SQLi"]
                                })
                                self.log(f"Second-order SQLi confirmed at {url} with full context replay")
                                verified_with_context = True
                                break
                
                # If not verified with context or context verification disabled, try normal verification
                if not verified_with_context or not context_verification_enabled:
                    resp = await self._async_fetch(url)
                    if resp:
                        html = resp._body
                        # Use enhanced SQL dialect validation
                        validation_result = validate_sqli_error_message(html)
                        if validation_result['is_valid_sqli']:
                            confidence = calculate_evidence_based_confidence(
                                evidence_strength='moderate',
                                baseline_excluded=True,
                                multiple_confirmations=False,
                                specificity='medium',
                                false_positive_resistance='medium'
                            )
                            await self._add_vulnerability({
                                "type":"Second-order SQLi","url":url,"parameter":"*",
                                "evidence":f"Marker found without context: {sqli_payload}",
                                "severity":"High","confidence":confidence,"cwe":CWE_MAP["SQLi"]
                            })
                            self.log(f"Second-order SQLi confirmed at {url} (without context replay)")
            except Exception as e:
                logging.debug(f"Verification error for {url}: {e}")
    
    async def _delayed_recrawl(self):
        """Re-crawl the application to discover pages that might contain injected content."""
        if not self.crawler_engine:
            return
        
        # Re-crawl starting from known entry points with a shallow depth
        pages_list = list(self.crawler_engine._get_crawled_pages_iterator())
        for page in pages_list[:5]:  # Limit to first 5 pages
            try:
                await self.crawler_engine.crawl(page['url'], max_depth=2)
            except Exception as e:
                logging.debug(f"Re-crawl error for {page['url']}: {e}")
    async def race_condition_tests(self):
        # Initialize FSM for state-aware race condition testing
        fsm = BusinessLogicFSM()
        
        target_urls = set()
        for page in self.crawler_engine._get_crawled_pages_iterator():
            if not page.get('html'):
                # Load HTML from disk if not already loaded
                html = self.crawler_engine._get_html_content(page['url'])
                page['html'] = html if html else ''
            html = page.get('html', '')
            soup = get_cached_soup(html, 'html.parser')
            for form in soup.find_all('form', method=lambda m: m and m.lower() == 'post'):
                form_text = form.get_text().lower()
                if any(kw in form_text for kw in ['redeem','coupon','transfer','checkout','order']):
                    action = urljoin(page['url'], form.get('action',''))
                    target_urls.add(action)
                    
                    # Learn state sequence from form discovery
                    current_state = fsm.detect_state_from_url(action)
                    fsm.add_transition('browse', current_state, 'form_discovery', {'url': action})
        
        if not target_urls:
            self.log("No race condition candidate endpoints found. Skipping race condition tests.")
            return
        for url in target_urls:
            # Enhanced race condition testing with FSM integration
            # FSM-aware race condition testing with state context
            await self._test_basic_race_condition(url, fsm_context=fsm)
            await self._test_race_condition_timing(url, fsm_context=fsm)
            await self._test_parallel_resource_allocation(url, fsm_context=fsm)
            await self._test_concurrent_state_transitions(url, fsm_context=fsm)
            await self._test_idempotency_violation(url, fsm_context=fsm)
        
        # Run advanced race condition tests on discovered endpoints with FSM
        await self._run_advanced_race_condition_tests(fsm)
        
        # Log FSM state at end of testing
        fsm_state = fsm.export_fsm_state()
        logging.info(f"FSM State after race condition testing: {fsm_state['current_state']}")
        logging.info(f"Learned {len(fsm_state['learned_sequences'])} state sequences")
    
    async def _run_advanced_race_condition_tests(self, fsm=None):
        try:
            # Initialize session manager for advanced tests
            session_manager = SessionStateManager()
            
            # Discover specific endpoints for advanced race condition tests
            forgot_password_urls = set()
            change_email_urls = set()
            transaction_urls = set()
            purchase_urls = set()
            
            for page in self.crawler_engine._get_crawled_pages_iterator():
                if not page.get('html'):
                    # Load HTML from disk if not already loaded
                    html = self.crawler_engine._get_html_content(page['url'])
                    page['html'] = html if html else ''
                html = page.get('html', '')
                soup = get_cached_soup(html, 'html.parser')
                
                # Discover password reset endpoints
                for form in soup.find_all('form'):
                    form_text = form.get_text().lower()
                    if 'forgot' in form_text or 'password' in form_text or 'reset' in form_text:
                        action = urljoin(page['url'], form.get('action', ''))
                        forgot_password_urls.add(action)
                
                # Discover email change endpoints
                if 'email' in form_text and 'change' in form_text:
                    action = urljoin(page['url'], form.get('action', ''))
                    change_email_urls.add(action)
                
                # Discover transaction endpoints
                if 'transfer' in form_text or 'payment' in form_text or 'transaction' in form_text:
                    action = urljoin(page['url'], form.get('action', ''))
                    transaction_urls.add(action)
                
                # Discover purchase endpoints
                if 'purchase' in form_text or 'buy' in form_text or 'checkout' in form_text:
                    action = urljoin(page['url'], form.get('action', ''))
                    purchase_urls.add(action)
            
            # Run advanced tests on discovered endpoints
            for forgot_url in forgot_password_urls:
                for change_url in change_email_urls:
                    session_id = session_manager.create_session()
                    try:
                        await self.test_token_validation_window(forgot_url, change_url, "test@example.com", session_manager, session_id)
                    except TypeError:
                        await self.test_token_validation_window(forgot_url, change_url, "test@example.com")
                    finally:
                        session_manager.destroy_session(session_id)
            
            for trans_url in transaction_urls:
                # Try multiple patterns for confirm URL
                possible_confirm_urls = [
                    trans_url.replace('/initiate', '/confirm'),
                    trans_url.replace('/start', '/complete'),
                    trans_url.replace('/begin', '/finalize'),
                    trans_url + '/confirm',
                    trans_url + '/complete'
                ]
                for confirm_url in possible_confirm_urls:
                    if confirm_url != trans_url:
                        session_id = session_manager.create_session()
                        await self.test_two_phase_transaction(trans_url, confirm_url, session_manager, session_id)
                        session_manager.destroy_session(session_id)
                        break
            
            for purchase_url in purchase_urls:
                session_id = session_manager.create_session()
                # Try to find corresponding cart URL for the purchase endpoint
                cart_url = purchase_url.replace('/purchase', '/cart').replace('/checkout', '/cart').replace('/buy', '/cart')
                if cart_url == purchase_url:
                    cart_url = purchase_url.rsplit('/', 1)[0] + '/cart'
                
                # Use new cart lock timing-aware race condition testing
                try:
                    await self._test_race_condition_with_cart_lock_timing(cart_url, purchase_url, session_manager, session_id)
                except Exception as e:
                    logging.debug(f"Cart lock timing test failed, falling back to inventory oversell test: {e}")
                    await self.test_inventory_oversell(purchase_url, None, 1, session_manager, session_id)
                
                session_manager.destroy_session(session_id)
            
        except Exception as e:
            logging.warning(f"Advanced race condition tests error: {e}")
    
    async def _test_basic_race_condition(self, url, session_manager: SessionStateManager = None, session_id: str = None, fsm_context=None):
        try:
            logging.info(f"[RACE CONDITION] Testing basic race condition at {url} with session {session_id}")
            
            # FSM-aware race condition testing
            current_state = 'unknown'
            next_state = 'unknown'
            fsm_should_test = True
            
            if fsm_context:
                current_state = fsm_context.detect_state_from_url(url)
                fsm_should_test = fsm_context.should_test_race_condition(current_state)
                logging.info(f"[FSM] Current state: {current_state}, Should test race condition: {fsm_should_test}")
                
                if fsm_should_test:
                    # Get optimal injection point from FSM
                    injection_point = fsm_context.get_optimal_race_injection_point(current_state)
                    if injection_point:
                        logging.info(f"[FSM] Using optimal injection point: {injection_point['window']}")
            
            if not fsm_should_test:
                logging.info(f"[FSM] Skipping race condition test for state: {current_state}")
                return
            
            # Enhanced race condition test using asyncio.gather() for better resource management
            # Use FSM-informed timing strategies if available
            time_deltas = [0, 10, 50, 100]  # Default timing deltas
            if fsm_context:
                injection_point = fsm_context.get_optimal_race_injection_point(current_state)
                if injection_point and 'time_deltas' in injection_point:
                    time_deltas = injection_point['time_deltas']
            
            # Use asyncio.gather() for better resource management instead of 50 separate event loops
            num_requests = 50
            
            async def synchronized_request(timing_delta=0):
                """Send request with timing delta for state-transition-aware testing."""
                try:
                    # Apply timing delta for state-transition-aware testing
                    if timing_delta > 0:
                        await asyncio.sleep(timing_delta / 1000.0)  # Convert to seconds
                    
                    # Send request
                    if session_manager and session_id:
                        session_cookies = await session_manager.get_session_cookies(session_id)
                        session_headers = await session_manager.get_session_headers(session_id)
                        resp = await self._async_fetch(url, method='POST', data={"test":"race"},
                                               cookies=session_cookies, headers=session_headers)
                    else:
                        resp = await self._async_fetch(url, method='POST', data={"test":"race"})
                    
                    return resp
                except Exception as e:
                    logging.debug(f"Synchronized request error: {e}")
                    return None
            
            # Execute all requests simultaneously using asyncio.gather() with timing deltas
            # This is much more efficient than creating 50 separate event loops
            tasks = []
            for i in range(num_requests):
                timing_delta = time_deltas[i % len(time_deltas)]
                tasks.append(synchronized_request(timing_delta))
            
            responses = await asyncio.gather(*tasks, return_exceptions=True)
            # Filter out exceptions
            responses = [resp for resp in responses if not isinstance(resp, Exception)]
            
            # Update session from responses if session manager provided
            if session_manager and session_id:
                for resp in responses:
                    if resp:
                        session_manager.update_session_from_response(session_id, resp)
            
            successful_responses = [resp for resp in responses if resp and resp.status == 200]
            
            if len(successful_responses) > 1:
                confidence = calculate_evidence_based_confidence(
                    evidence_strength='medium',
                    baseline_excluded=True,
                    multiple_confirmations=True,
                    specificity='medium',
                    false_positive_resistance='medium'
                )
                
                # Add FSM context to vulnerability report
                race_vuln = {
                    "type":"Potential Race Condition","url":url,"parameter":"*",
                    "evidence":f"{len(successful_responses)}/{num_requests} synchronized requests succeeded",
                    "severity":"Medium","confidence":confidence,"cwe":CWE_MAP["RaceCondition"],
                    "race_test_results": {
                        "success_rate": len(successful_responses)/num_requests,
                        "timing_anomalies": 0,
                        "consistency_score": 0.8,
                        "race_window_size": num_requests
                    },
                    "fsm_context": {
                        "state": current_state,
                        "timing_strategy": time_deltas,
                        "state_aware": fsm_context is not None
                    } if fsm_context else None
                }
                await self._add_vulnerability(race_vuln)
                
                # Update FSM with successful transition if context available
                if fsm_context:
                    fsm_context.add_transition(current_state, next_state, 'race_condition_test', {
                        'url': url,
                        'success': True,
                        'responses': len(successful_responses)
                    })
        except Exception as e:
            logging.warning(f"Basic race condition test error: {e}")
    
    async def _test_parallel_resource_allocation(self, url, session_manager: SessionStateManager = None, session_id: str = None, fsm_context=None):
        try:
            logging.info(f"[RACE CONDITION] Testing parallel resource allocation at {url} with session {session_id}")
            
            # FSM-aware testing
            current_state = 'unknown'
            if fsm_context:
                current_state = fsm_context.detect_state_from_url(url)
                if not fsm_context.should_test_race_condition(current_state):
                    logging.info(f"[FSM] Skipping parallel resource allocation test for state: {current_state}")
                    return
            
            # Test parallel resource allocation using ThreadPoolExecutor and Barrier
            import concurrent.futures
            import threading
            
            num_requests = 50
            results = []
            barrier = threading.Barrier(num_requests)
            
            resource_data = {
                'resource_id': 'test_resource_123',
                'user_id': 'test_user_456',
                'allocation_type': 'exclusive'
            }
            
            def allocate_resource(request_id):
                """Allocate resource with synchronized timing."""
                try:
                    test_data = resource_data.copy()
                    test_data['request_id'] = request_id
                    start_time = time.time()
                    
                    # Wait for all threads to be ready
                    barrier.wait()
                    
                    # Send request immediately after barrier release
                    if session_manager and session_id:
                        loop = asyncio.new_event_loop()
                        asyncio.set_event_loop(loop)
                        try:
                            session_cookies = loop.run_until_complete(session_manager.get_session_cookies(session_id))
                            session_headers = loop.run_until_complete(session_manager.get_session_headers(session_id))
                            resp = loop.run_until_complete(
                                self._async_fetch(url, method='POST', data=test_data,
                                               cookies=session_cookies, headers=session_headers)
                            )
                        finally:
                            loop.close()
                    else:
                        loop = asyncio.new_event_loop()
                        asyncio.set_event_loop(loop)
                        try:
                            resp = loop.run_until_complete(
                                self._async_fetch(url, method='POST', data=test_data)
                            )
                        finally:
                            loop.close()
                    
                    end_time = time.time()
                    return {
                        'request_id': request_id,
                        'success': resp and resp.status == 200,
                        'response_time': end_time - start_time,
                        'response': resp.text if resp else None
                    }
                except Exception as e:
                    logging.debug(f"Resource allocation error: {e}")
                    return None
            
            # Execute all requests simultaneously using ThreadPoolExecutor
            with concurrent.futures.ThreadPoolExecutor(max_workers=num_requests) as executor:
                request_ids = [f"alloc_{i}_{uuid.uuid4().hex[:8]}" for i in range(num_requests)]
                futures = [executor.submit(allocate_resource, rid) for rid in request_ids]
                results = [future.result() for future in concurrent.futures.as_completed(futures)]
            
            # Update session from responses if session manager provided
            if session_manager and session_id:
                for result in results:
                    if result and result.get('success'):
                        # Create a proper response object for session update
                        response_obj = self._create_response_object_from_result(result)
                        session_manager.update_session_from_response(session_id, response_obj)
            
            successful = [r for r in results if r and r['success']]
            
            # If more than expected allocations succeed, race condition exists
            if len(successful) > 1:
                confidence = calculate_evidence_based_confidence(
                    evidence_strength='critical',
                    baseline_excluded=True,
                    multiple_confirmations=True,
                    specificity='high',
                    false_positive_resistance='high'
                )
                race_vuln = {
                    "type": "Parallel Resource Allocation Race Condition",
                    "url": url,
                    "parameter": "resource_id,user_id",
                    "evidence": f"{len(successful)} exclusive resource allocations succeeded concurrently",
                    "severity": "Critical",
                    "confidence": confidence,
                    "cwe": CWE_MAP["RaceCondition"],
                    "race_test_results": {
                        "success_rate": len(successful)/num_requests,
                        "timing_anomalies": sum(1 for r in results if r and r.get('response_time', 0) > 1.0),
                        "consistency_score": 0.9,
                        "race_window_size": num_requests
                    }
                }
                await self._add_vulnerability(race_vuln)
                logging.warning(f"[RACE CONDITION] CRITICAL: {len(successful)} exclusive allocations succeeded")
            
        except Exception as e:
            logging.warning(f"Parallel resource allocation test error: {e}")
    
    def _create_response_object_from_result(self, result):
        """Create a proper response object from race condition test result"""
        class ResponseObject:
            def __init__(self, result_data):
                self._result = result_data
                self.text = result_data.get('response', '')
                self.status = result_data.get('status', 200)
                self.headers = result_data.get('headers', {})
                self._content = self.text.encode() if isinstance(self.text, str) else self.text
                
            async def text(self):
                return self.text
                
            async def read(self):
                return self._content
                
            async def json(self):
                try:
                    return json.loads(self.text)
                except:
                    return {}
        
        return ResponseObject(result)
    
    async def _test_concurrent_state_transitions(self, url, session_manager: SessionStateManager = None, session_id: str = None, fsm_context=None):
        try:
            logging.info(f"[RACE CONDITION] Testing concurrent state transitions at {url} with session {session_id}")
            
            # FSM-aware testing
            current_state = 'unknown'
            if fsm_context:
                current_state = fsm_context.detect_state_from_url(url)
                if not fsm_context.should_test_race_condition(current_state):
                    logging.info(f"[FSM] Skipping concurrent state transitions test for state: {current_state}")
                    return
            
            # Test concurrent state transitions using ThreadPoolExecutor and Barrier
            import concurrent.futures
            import threading
            
            state_data = {
                'entity_id': 'entity_789',
                'current_state': 'pending',
                'target_state': 'approved'
            }
            
            target_states = ['approved', 'rejected', 'cancelled', 'pending']
            num_requests = len(target_states)
            barrier = threading.Barrier(num_requests)
            
            def transition_state(request_id, target_state):
                """Transition state with synchronized timing."""
                try:
                    test_data = state_data.copy()
                    test_data['target_state'] = target_state
                    test_data['request_id'] = request_id
                    
                    # Wait for all threads to be ready
                    barrier.wait()
                    
                    # Send request immediately after barrier release
                    loop = asyncio.new_event_loop()
                    asyncio.set_event_loop(loop)
                    try:
                        # Use session manager if available
                        if session_manager and session_id:
                            session_cookies = session_manager.get_session_cookies(session_id)
                            session_headers = session_manager.get_session_headers(session_id)
                            resp = loop.run_until_complete(
                                self._async_fetch(url, method='POST', data=test_data,
                                               cookies=session_cookies, headers=session_headers)
                            )
                        else:
                            resp = loop.run_until_complete(
                                self._async_fetch(url, method='POST', data=test_data)
                            )
                    finally:
                        loop.close()
                    
                    return {
                        'request_id': request_id,
                        'target_state': target_state,
                        'success': resp and resp.status == 200,
                        'response': resp.text if resp else None
                    }
                except Exception as e:
                    logging.debug(f"State transition error: {e}")
                    return None
            
            # Execute all requests simultaneously using ThreadPoolExecutor
            with concurrent.futures.ThreadPoolExecutor(max_workers=num_requests) as executor:
                futures = [executor.submit(transition_state, f"state_{i}", state) 
                          for i, state in enumerate(target_states)]
                results = [future.result() for future in concurrent.futures.as_completed(futures)]
            
            # Update session from responses if session manager provided
            if session_manager and session_id:
                for result in results:
                    if result and result['success']:
                        # Store the state transition result in session
                        session_manager.set_session_state(session_id, f"state_{result['request_id']}", result['target_state'])
            
            successful = [r for r in results if r and r['success']]
            
            # If multiple conflicting state transitions succeed, race condition exists
            if len(successful) > 1:
                successful_states = [r['target_state'] for r in successful]
                confidence = calculate_evidence_based_confidence(
                    evidence_strength='high',
                    baseline_excluded=True,
                    multiple_confirmations=True,
                    specificity='high',
                    false_positive_resistance='high'
                )
                await self._add_vulnerability({
                    "type": "Concurrent State Transition Race Condition",
                    "url": url,
                    "parameter": "target_state",
                    "evidence": f"Multiple conflicting state transitions succeeded: {successful_states}",
                    "severity": "High",
                    "confidence": confidence,
                    "cwe": CWE_MAP["RaceCondition"],
                    "race_test_results": {
                        "success_rate": len(successful_states)/num_requests,
                        "timing_anomalies": 0,
                        "consistency_score": 0.7,
                        "race_window_size": num_requests
                    }
                })
            
        except Exception as e:
            logging.warning(f"Concurrent state transition test error: {e}")
    
