    async def _analyze_browser_auth_results(self, auth_url, auth_result):
        """
        Analyze browser authentication results for security issues.
        
        Args:
            auth_url: OAuth authorization URL
            auth_result: Authentication result from BrowserAuthHelper
        """
        try:
            # Check for insecure token exposure in URL
            final_url = auth_result.get('url', '')
            if 'access_token=' in final_url or 'id_token=' in final_url:
                await self._add_vulnerability({
                    "type": "OAuth Token Exposure in URL",
                    "url": auth_url,
                    "parameter": "access_token",
                    "evidence": "Access tokens exposed in URL fragment after browser authentication",
                    "severity": "High",
                    "confidence": 90,
                    "cwe": CWE_MAP["OAuthTokenExposure"],
                    "oauth_test_results": {
                        "test_type": "browser_auth_analysis",
                        "token_in_url": True,
                        "final_url": final_url
                    }
                })
            
            # Check for missing HTTP-only and Secure flags on cookies
            cookies = auth_result.get('cookies', {})
            for cookie_name, cookie_value in cookies.items():
                # This is a simplified check - in real implementation would check cookie attributes
                if 'session' in cookie_name.lower() or 'auth' in cookie_name.lower():
                    logging.debug(f"[OAUTH BROWSER] Found authentication cookie: {cookie_name}")
            
            # Check for insecure redirect destinations
            if 'http://' in final_url and 'localhost' not in final_url:
                await self._add_vulnerability({
                    "type": "OAuth Insecure Redirect",
                    "url": auth_url,
                    "parameter": "redirect_uri",
                    "evidence": f"OAuth flow redirected to insecure HTTP endpoint: {final_url}",
                    "severity": "Medium",
                    "confidence": 75,
                    "cwe": CWE_MAP["OAuthInsecureRedirect"],
                    "oauth_test_results": {
                        "test_type": "browser_auth_analysis",
                        "insecure_redirect": True,
                        "redirect_url": final_url
                    }
                })
                
        except Exception as e:
            logging.warning(f"Browser auth results analysis error: {e}")
    
    async def complex_purchase_sequence_automation(self):
        self.log("Testing complex purchase sequence automation...")
        purchase_endpoints = set()
        
        # Initialize session state manager for multi-step flows
        session_manager = SessionStateManager()
        
        # Discover purchase-related endpoints
        for page in self.crawler_engine.crawled_pages:
            page_data = await self.loop.run_in_executor(None, self.scan_state_manager.get_page_hash, page['url'])
            if not page_data:
                continue
            html = page_data.get('html_content', '')
            soup = get_cached_soup(html, 'html.parser')
            
            purchase_keywords = ['cart', 'checkout', 'purchase', 'order', 'payment', 'shipping', 'billing']
            
            for link in soup.find_all('a', href=True):
                href = link['href'].lower()
                if any(kw in href for kw in purchase_keywords):
                    full_url = urljoin(page['url'], link['href'])
                    purchase_endpoints.add(full_url)
            
            for form in soup.find_all('form'):
                form_text = form.get_text().lower()
                if any(kw in form_text for kw in purchase_keywords):
                    action = urljoin(page['url'], form.get('action', ''))
                    purchase_endpoints.add(action)
        
        # Store discovered purchase endpoints for interconnection with other tests
        self.discovered_purchase_endpoints = purchase_endpoints
        
        # Test complex purchase sequences with proper session management
        for purchase_url in purchase_endpoints:
            # Create a fresh session for each purchase flow
            session_id = session_manager.create_session()
            
            await self._test_multi_step_purchase_race(purchase_url, session_manager, session_id)
            await self._test_cart_manipulation_sequence(purchase_url, session_manager, session_id)
            await self._test_price_tampering_sequence(purchase_url, session_manager, session_id)
            await self._test_coupon_stacking_sequence(purchase_url, session_manager, session_id)
            await self._test_payment_bypass_sequence(purchase_url, session_manager, session_id)
            
            # Interconnect with inventory oversell test
            await self.test_inventory_oversell(purchase_url, None, 1, session_manager, session_id)
            
            # Interconnect with race condition tests on purchase endpoints with FSM context
            fsm_context = self.business_logic_fsm if self.fsm_aware_testing_enabled else None
            await self._test_basic_race_condition(purchase_url, session_manager, session_id, fsm_context=fsm_context)
            await self._test_parallel_resource_allocation(purchase_url, session_manager, session_id, fsm_context=fsm_context)
            
            # Clean up session
            session_manager.destroy_session(session_id)
    
    async def _test_multi_step_purchase_race(self, checkout_url, session_manager: SessionStateManager, session_id: str):
        try:
            logging.info(f"[PURCHASE SEQUENCE] Testing multi-step purchase race at {checkout_url} with session {session_id}")
            
            # Auto-detect parameter names from cart forms
            detected_params = await self._detect_cart_form_parameters(checkout_url)
            product_id_param = detected_params.get('product_id', 'product_id')
            quantity_param = detected_params.get('quantity', 'quantity')
            
            # Try cart lock timing-aware analysis first
            cart_url = checkout_url.replace('/checkout', '/cart').replace('/purchase', '/cart')
            if cart_url == checkout_url:
                cart_url = checkout_url.rsplit('/', 1)[0] + '/cart'
            
            try:
                lock_analysis = await self._replicate_user_journey_timing(cart_url, checkout_url, session_manager, session_id)
                if lock_analysis.get('timing_windows') and lock_analysis['timing_windows'].get('avg_lock_duration'):
                    logging.info(f"[PURCHASE SEQUENCE] Using detected lock timing: {lock_analysis['timing_windows']['avg_lock_duration']*1000:.2f}ms")
            except Exception as e:
                logging.debug(f"Lock timing analysis not available: {e}")
                lock_analysis = None
            
            # Simulate a multi-step checkout process with race conditions
            cart_data = {
                product_id_param: 'prod_123',
                quantity_param: 1
            }
            
            # Step 1: Add to cart with session management
            cart_add_url = checkout_url.replace('/checkout', '/cart/add')
            session_cookies = session_manager.get_session_cookies(session_id)
            session_headers = session_manager.get_session_headers(session_id)
            
            cart_resp = await self._async_fetch(cart_add_url, method='POST', data=cart_data, 
                                               cookies=session_cookies, headers=session_headers)
            
            # Update session from response
            session_manager.update_session_from_response(session_id, cart_resp)
            
            if not cart_resp or cart_resp.status != 200:
                return
            
            # Store cart_id from response if available
            if hasattr(cart_resp, '_body'):
                import re
                cart_id_match = re.search(r'cart[_-]?id["\']?\s*[:=]\s*["\']?([a-zA-Z0-9_-]+)', cart_resp._body)
                if cart_id_match:
                    session_manager.set_session_state(session_id, 'cart_id', cart_id_match.group(1))
                    logging.debug(f"Stored cart_id in session: {cart_id_match.group(1)}")
            
            # Step 2: Initiate checkout with concurrent shipping method selection
            cart_id = session_manager.get_session_state(session_id, 'cart_id') or 'test_cart_123'
            checkout_data = {
                'cart_id': cart_id,
                'shipping_method': 'standard'
            }
            
            # Use lock timing if available to synchronize attacks
            if lock_analysis and lock_analysis.get('timing_windows'):
                lock_duration = lock_analysis['timing_windows'].get('avg_lock_duration', 0.010)
                logging.info(f"[PURCHASE SEQUENCE] Synchronizing attacks to {lock_duration*1000:.2f}ms lock window")
            
            async def initiate_checkout_with_race(shipping_method):
                # Get fresh session data for each concurrent request
                test_cookies = session_manager.get_session_cookies(session_id)
                test_headers = session_manager.get_session_headers(session_id)
                
                test_data = checkout_data.copy()
                test_data['shipping_method'] = shipping_method
                resp = await self._async_fetch(checkout_url, method='POST', data=test_data,
                                             cookies=test_cookies, headers=test_headers)
                
                # Update session from each response
                session_manager.update_session_from_response(session_id, resp)
                
                return {
                    'shipping_method': shipping_method,
                    'success': resp and resp.status == 200,
                    'response': resp.text if resp else None
                }
            
            # Race between different shipping methods
            shipping_methods = ['standard', 'express', 'overnight']
            tasks = [initiate_checkout_with_race(method) for method in shipping_methods]
            done, pending = await safe_async_wait(tasks, timeout=60, return_when=asyncio.ALL_COMPLETED)
            
            if pending:
                for task in pending:
                    task.cancel()
            
            results = [task.result() for task in done if not task.cancelled()]
            successful = [r for r in results if r['success']]
            
            if len(successful) > 1:
                await self._add_vulnerability({
                    "type": "Multi-Step Purchase Race Condition",
                    "url": checkout_url,
                    "parameter": "shipping_method",
                    "evidence": f"{len(successful)} shipping methods accepted simultaneously with proper session management",
                    "severity": "High",
                    "confidence": 85,
                    "cwe": CWE_MAP["MultiStepPurchase"]
                })
            
        except Exception as e:
            logging.warning(f"Multi-step purchase race test error: {e}")
    
    async def _test_cart_manipulation_sequence(self, cart_url, session_manager: SessionStateManager, session_id: str):
        try:
            logging.info(f"[CART SEQUENCE] Testing cart manipulation at {cart_url} with session {session_id}")
            
            # Auto-detect parameter names from cart forms
            detected_params = await self._detect_cart_form_parameters(cart_url)
            product_id_param = detected_params.get('product_id', 'product_id')
            quantity_param = detected_params.get('quantity', 'quantity')
            
            # Test cart manipulation sequence
            product_id = 'prod_456'
            
            # Sequence: Add items, modify quantities, remove items concurrently
            async def cart_operation(operation, quantity=None):
                # Get fresh session data for each operation
                session_cookies = session_manager.get_session_cookies(session_id)
                session_headers = session_manager.get_session_headers(session_id)
                
                if operation == 'add':
                    data = {product_id_param: product_id, quantity_param: quantity or 1}
                elif operation == 'update':
                    data = {product_id_param: product_id, quantity_param: quantity or 10}
                elif operation == 'remove':
                    data = {product_id_param: product_id}
                else:
                    return None
                
                resp = await self._async_fetch(cart_url, method='POST', data=data,
                                             cookies=session_cookies, headers=session_headers)
                
                # Update session from response
                session_manager.update_session_from_response(session_id, resp)
                
                return {
                    'operation': operation,
                    'success': resp and resp.status == 200,
                    'quantity': quantity
                }
            
            # Concurrent cart operations
            operations = [
                ('add', 1),
                ('add', 1),
                ('update', 5),
                ('update', 10),
                ('remove', None)
            ]
            
            tasks = [cart_operation(op, qty) for op, qty in operations]
            done, pending = await safe_async_wait(tasks, timeout=60, return_when=asyncio.ALL_COMPLETED)
            
            if pending:
                for task in pending:
                    task.cancel()
            
            results = [task.result() for task in done if not task.cancelled()]
            successful = [r for r in results if r['success']]
            
            # Check if cart operations violate business logic
            if len(successful) > 3:
                await self._add_vulnerability({
                    "type": "Cart Manipulation Race Condition",
                    "url": cart_url,
                    "parameter": "*",
                    "evidence": f"{len(successful)} concurrent cart operations succeeded",
                    "severity": "Medium",
                    "confidence": 75,
                    "cwe": CWE_MAP["CartManipulation"]
                })
            
        except Exception as e:
            logging.warning(f"Cart manipulation sequence test error: {e}")
    
